  // Défibrillateurs are now loaded exclusively from the tenant's Google Spreadsheet (no Firestore onSnapshot listener)

  const [isRefreshingDefibs, setIsRefreshingDefibs] = useState<boolean>(false);
  const [isRefreshingAutresMateriels, setIsRefreshingAutresMateriels] = useState<boolean>(false);
  const [isRefreshingClients, setIsRefreshingClients] = useState<boolean>(false);

  const getDeletedDefibKeys = (tId: string = tenantId || 'demo'): string[] => {
    try {
      const raw = localStorage.getItem(`defib_${tId}_deleted_defib_keys`);
      if (raw) {
        const parsed = JSON.parse(raw);
        if (Array.isArray(parsed)) return parsed.map(s => String(s).trim().toLowerCase()).filter(Boolean);
      }
    } catch (_) {}
    return [];
  };

  const recordDeletedDefibKeys = (keys: (string | undefined | null)[], tId: string = tenantId || 'demo') => {
    try {
      const existing = getDeletedDefibKeys(tId);
      const toAdd = keys.filter(Boolean).map(k => String(k).trim().toLowerCase());
      const combined = Array.from(new Set([...existing, ...toAdd]));
      localStorage.setItem(`defib_${tId}_deleted_defib_keys`, JSON.stringify(combined));
      const isDNum = /^d\d+$/i.test(tId);
      if (isDNum) {
        const numOnly = tId.replace(/^d/i, '');
        localStorage.setItem(`defib_D${numOnly}_deleted_defib_keys`, JSON.stringify(combined));
        localStorage.setItem(`defib_d${numOnly}_deleted_defib_keys`, JSON.stringify(combined));
      }
      if (toAdd.length > 0) {
        fetch('/api/sync-deleted-defib-keys', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ tenantId: tId, keys: toAdd })
        }).catch(() => {});
      }
    } catch (_) {}
  };

  useEffect(() => {
    (async () => {
      try {
        const tId = tenantId || 'demo';
        if (tId.toLowerCase() === 'megaadmin' || localStorage.getItem('defib_logged_user_role') === 'megaadmin') return;
        const remoteKeys = await fetchRemoteDeletedDefibKeys(tId);
        if (remoteKeys.length > 0) {
          const localKeys = getDeletedDefibKeys(tId);
          const combined = Array.from(new Set([...localKeys, ...remoteKeys]));
          localStorage.setItem(`defib_${tId}_deleted_defib_keys`, JSON.stringify(combined));
          const numOnly = tId.replace(/^d/i, '');
          if (/^\d+$/.test(numOnly)) {
            localStorage.setItem(`defib_D${numOnly}_deleted_defib_keys`, JSON.stringify(combined));
            localStorage.setItem(`defib_d${numOnly}_deleted_defib_keys`, JSON.stringify(combined));
          }

          // Immediately prune deleted items from active React state and local IndexedDB
          const delSet = new Set(combined);
          setDefibrillateurs(prev => {
            if (!Array.isArray(prev) || prev.length === 0) return prev;
            const filtered = prev.filter(df => !isDefibInDeletedList(df, delSet));
            if (filtered.length !== prev.length) {
              idbSet(`defib_${tId}_defibrillateurs_v110`, filtered).catch(() => {});
              if (/^\d+$/.test(numOnly)) {
                idbSet(`defib_D${numOnly}_defibrillateurs_v110`, filtered).catch(() => {});
                idbSet(`defib_d${numOnly}_defibrillateurs_v110`, filtered).catch(() => {});
              }
            }
            return filtered;
          });
        }
        const activeKeys = getDeletedDefibKeys(tId);
        if (activeKeys.length > 0) {
          fetch('/api/sync-deleted-defib-keys', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ tenantId: tId, keys: activeKeys })
          }).catch(() => {});
        }
      } catch (_) {}
    })();
  }, [tenantId]);

  const lastLocalSheetMutationRef = React.useRef<number>(0);

  const isDefibInDeletedList = (df: any, deletedKeys: Set<string>): boolean => {
    if (!df) return false;
    const id = df.id ? String(df.id).trim().toLowerCase() : '';
    const identifiant = df.identifiant ? String(df.identifiant).trim().toLowerCase() : '';
    if (id.startsWith('sheet_df_') || identifiant.startsWith('sheet_df_')) return true;
    if (!deletedKeys || deletedKeys.size === 0) return false;
    // If the spreadsheet row has an explicit identifiant/id, only match by its unique id/identifiant
    // (never by numeroSerie, which is often shared or 'Non renseigné' across thousands of rows)
    if (identifiant || id) {
      return Boolean((id && deletedKeys.has(id)) || (identifiant && deletedKeys.has(identifiant)));
    }
    const numSerie = df.numeroSerie || df.num_serie ? String(df.numeroSerie || df.num_serie).trim().toLowerCase() : '';
    if (!numSerie || numSerie === 'non renseigné' || numSerie === 'n/a' || numSerie === '-') return false;
    return deletedKeys.has(numSerie);
  };

  const [defibSheetStats, setDefibSheetStats] = useState<any>(() => {
    if (typeof window !== 'undefined') {
      try {
        const tid = localStorage.getItem('defib_tenant_id') || 'demo';
        const raw = localStorage.getItem(`defib_${tid}_defib_sheet_stats`);
        if (raw) return JSON.parse(raw);
      } catch (_) {}
    }
    return null;
  });

  const persistDefibCache = (tid: string, items: Defibrillateur[], stats?: any) => {
    if (stats) {
      setDefibSheetStats(stats);
      try {
        for (const k of [tid, tid.toUpperCase(), tid.toLowerCase()]) {
          localStorage.setItem(`defib_${k}_defib_sheet_stats`, JSON.stringify(stats));
        }
      } catch (_) {}
    }
    if (Array.isArray(items) && items.length > 0) {
      for (const k of [tid, tid.toUpperCase(), tid.toLowerCase()]) {
        idbSet(`defib_${k}_defibrillateurs_v110`, items).catch(() => {});
      }
    }
  };

  const fetchSheetCollectionInBatches = async (
    activeTid: string,
    tabType: 'defibrillateurs' | 'autresMateriels' | 'clients',
    spreadsheetUrl: string,
    forceRefresh: boolean,
    onFirstBatch: (json: any, firstItems: any[]) => void,
    onBatchAppended: (allAccumulatedItems: any[], loadedCount: number, totalCount: number, json?: any) => void,
    isCancelledFn?: () => boolean
  ) => {
    const FIRST_CHUNK_SIZE = 5000;
    const NEXT_CHUNK_SIZE = 20000;
    let offset = 0;
    let hasMore = true;
    const accumulated: any[] = [];

    while (hasMore) {
      if (isCancelledFn && isCancelledFn()) return;
      const isFirst = offset === 0;
      const chunkSize = isFirst ? FIRST_CHUNK_SIZE : NEXT_CHUNK_SIZE;
      const url = `/api/sheets/data?tenantId=${encodeURIComponent(activeTid)}&type=${encodeURIComponent(tabType)}&forceRefresh=${isFirst && forceRefresh}&offset=${offset}&limit=${chunkSize}&spreadsheetUrl=${encodeURIComponent(spreadsheetUrl)}`;

      let json: any = null;
      for (let attempt = 1; attempt <= 3; attempt++) {
        try {
          if (isCancelledFn && isCancelledFn()) return;
          const res = await fetch(url);
          if (res.ok) {
            json = await res.json();
            break;
          }
        } catch (_) {}
        if (attempt < 3) {
          await new Promise(r => setTimeout(r, 250 * attempt));
        }
      }

      if (!json || (isCancelledFn && isCancelledFn())) break;

      const batchItems = Array.isArray(json.items) ? json.items : [];
      accumulated.push(...batchItems);

      if (isFirst) {
        onFirstBatch(json, [...accumulated]);
      } else {
        onBatchAppended([...accumulated], accumulated.length, json.totalCount || accumulated.length, json);
      }

      if (json.hasMore && batchItems.length > 0 && typeof json.nextOffset === 'number' && json.nextOffset > offset) {
        offset = json.nextOffset;
      } else {
        hasMore = false;
      }
    }
  };

  const manualDefibRefreshRunIdRef = React.useRef<number>(0);

  const handleManualRefreshDefibs = async (forceRemote = true) => {
    const runId = ++manualDefibRefreshRunIdRef.current;
    setIsRefreshingDefibs(true);
    if (defibrillateurs.length === 0) {
      setIsDefibLoading(true);
    }
    const initialCount = defibSheetStats?.totalCount || defibrillateurs.length || 0;
    setDefibLoadingProgress({
      current: 0,
      total: initialCount,
      percent: 5,
      message: 'Actualisation des données en direct depuis le serveur...'
    });
    try {
      const activeTenant = tenantId || 'demo';

      // 1. Fetch persistent deleted keys in parallel without blocking sheet fetch if slow
      try {
        const remoteDeletedKeys = await Promise.race([
          fetchRemoteDeletedDefibKeys(activeTenant),
          new Promise<string[]>(r => setTimeout(() => r([]), 1200)),
        ]);
        if (remoteDeletedKeys.length > 0) {
          const localKeys = getDeletedDefibKeys(activeTenant);
          const combined = Array.from(new Set([...localKeys, ...remoteDeletedKeys]));
          localStorage.setItem(`defib_${activeTenant}_deleted_defib_keys`, JSON.stringify(combined));
        }
      } catch (_) {}

      const delSet = new Set(getDeletedDefibKeys(activeTenant));

      // 1b. Fetch from the tenant's Google Spreadsheet for Défibrillateurs in progressive chunks
      const rawUrl =
        companyInfo?.spreadsheetDefibrillateurs ||
        companyInfo?.spreadsheetDefibrillateursUrl ||
        localStorage.getItem(`defib_${activeTenant}_spreadsheet_defibrillateurs`) ||
        localStorage.getItem(`defib_${activeTenant.toUpperCase()}_spreadsheet_defibrillateurs`) ||
        localStorage.getItem(`defib_${activeTenant.toLowerCase()}_spreadsheet_defibrillateurs`) ||
        '';
      const defibSheetUrl = (rawUrl.includes('1tB1e41') || rawUrl.includes('2mX5O6r9hD0i3Z9m')) ? '' : rawUrl.trim();

      if (defibSheetUrl) {
        lastLoadedSheetUrlsRef.current.tenant = activeTenant;
        lastLoadedSheetUrlsRef.current.defibs = defibSheetUrl;
      }

      await fetchSheetCollectionInBatches(
        activeTenant,
        'defibrillateurs',
        defibSheetUrl,
        forceRemote,
        (json, firstItems) => {
          if (json.spreadsheetUrl && typeof json.spreadsheetUrl === 'string') {
            const cleanUrl = json.spreadsheetUrl.trim();
            if (cleanUrl && !cleanUrl.includes('1tB1e41') && !cleanUrl.includes('2mX5O6r9hD0i3Z9m')) {
              lastLoadedSheetUrlsRef.current.tenant = activeTenant;
              lastLoadedSheetUrlsRef.current.defibs = cleanUrl;
              try {
                for (const k of [activeTenant, activeTenant.toUpperCase(), activeTenant.toLowerCase()]) {
                  localStorage.setItem(`defib_${k}_spreadsheet_defibrillateurs`, cleanUrl);
                }
              } catch (_) {}
              setCompanyInfo(prev =>
                prev.spreadsheetDefibrillateurs === cleanUrl
                  ? prev
                  : { ...prev, spreadsheetDefibrillateurs: cleanUrl, spreadsheetDefibrillateursUrl: cleanUrl }
              );
            }
          }
          if (!json.fromSpreadsheet || json.status === 'no_spreadsheet') {
            setDefibrillateurs([]);
            setDefibSheetStats(null);
            idbSet(`defib_${activeTenant}_defibrillateurs_v110`, []).catch(() => {});
            setIsDefibLoading(false);
            return;
          }
          const filtered = firstItems.filter((df: any) => !isDefibInDeletedList(df, delSet));
          setDefibrillateurs(filtered);
          if (filtered.length > 0) {
            persistDefibCache(activeTenant, filtered, json.stats);
          } else if (json.stats) {
            setDefibSheetStats(json.stats);
          }
          const tot = json.totalCount || filtered.length;
          setDefibLoadingProgress({
            current: filtered.length,
            total: tot,
            percent: tot > 0 ? Math.min(100, Math.round((filtered.length / tot) * 100)) : 100,
            message: `Chargement ${filtered.length.toLocaleString('en-US')}/${tot.toLocaleString('en-US')}...`,
          });
          setIsDefibLoading(false);
        },
        (allItems, _loadedCount, totalCount, batchJson) => {
          const filtered = allItems.filter((df: any) => !isDefibInDeletedList(df, delSet));
          if (filtered.length > 0) {
            setDefibrillateurs(filtered);
            persistDefibCache(activeTenant, filtered, batchJson?.stats);
          }
          setDefibLoadingProgress({
            current: filtered.length,
            total: totalCount || filtered.length,
            percent: totalCount > 0 ? Math.min(100, Math.round((filtered.length / totalCount) * 100)) : 100,
            message: `Chargement ${filtered.length.toLocaleString('en-US')}/${(totalCount || filtered.length).toLocaleString('en-US')}, Terminé.`,
          });
        },
        () => manualDefibRefreshRunIdRef.current !== runId
      );

      // Ensure Clients spreadsheet is also loaded if clients state is currently empty
      if (clients.length === 0) {
        const rawUrlClients =
          companyInfo?.spreadsheetClients ||
          companyInfo?.spreadsheetClientsUrl ||
          localStorage.getItem(`defib_${activeTenant}_spreadsheet_clients`) ||
          localStorage.getItem(`defib_${activeTenant.toUpperCase()}_spreadsheet_clients`) ||
          localStorage.getItem(`defib_${activeTenant.toLowerCase()}_spreadsheet_clients`) ||
          '';
        const clientSheetUrl = (rawUrlClients.includes('1tB1e41') || rawUrlClients.includes('2mX5O6r9hD0i3Z9m')) ? '' : rawUrlClients.trim();
        fetchSheetCollectionInBatches(
          activeTenant,
          'clients',
          clientSheetUrl,
          false,
          (_json, firstItems) => {
            if (!_json.fromSpreadsheet || _json.status === 'no_spreadsheet') {
              setClients([]);
              idbSet(`defib_${activeTenant}_clients`, []).catch(() => {});
              return;
            }
            if (_json.stats?.clientVolumes) {
              setDefibSheetStats(prev => (prev ? { ...prev, clientVolumes: _json.stats.clientVolumes } : _json.stats));
            }
            const validClients = firstItems.filter(
              (cl: any) =>
                cl &&
                !String(cl.id || '').startsWith('sheet_cli_') &&
                !String(cl.clientIdField || '').startsWith('sheet_cli_')
            );
            setClients(validClients);
            idbSet(`defib_${activeTenant}_clients_v2`, validClients).catch(() => {});
          },
          (allItems) => {
            const validClients = allItems.filter(
              (cl: any) =>
                cl &&
                !String(cl.id || '').startsWith('sheet_cli_') &&
                !String(cl.clientIdField || '').startsWith('sheet_cli_')
            );
            setClients(validClients);
            idbSet(`defib_${activeTenant}_clients_v2`, validClients).catch(() => {});
          }
        ).catch(() => {});
      }

      setTimeout(() => setIsDefibLoading(false), 200);
      return;
    } catch (err) {
      console.warn('Manual refresh error:', err);
    } finally {
      if (manualDefibRefreshRunIdRef.current === runId) {
        setTimeout(() => {
          setIsRefreshingDefibs(false);
          setIsDefibLoading(false);
        }, 400);
      }
    }
  };

  const handleManualRefreshAutresMateriels = async () => {
    setIsRefreshingAutresMateriels(true);
    try {
      const activeTenant = tenantId || 'demo';
      const urlAutres =
        companyInfo?.spreadsheetAutresMateriels ||
        companyInfo?.spreadsheetAutresMaterielsUrl ||
        localStorage.getItem(`defib_${activeTenant}_spreadsheet_autres_materiels`) ||
        localStorage.getItem(`defib_${activeTenant.toUpperCase()}_spreadsheet_autres_materiels`) ||
        localStorage.getItem(`defib_${activeTenant.toLowerCase()}_spreadsheet_autres_materiels`) ||
        '';

      await fetchSheetCollectionInBatches(
        activeTenant,
        'autresMateriels',
        urlAutres,
        true,
        (json, firstItems) => {
          if (!json.fromSpreadsheet || json.status === 'no_spreadsheet') {
            setOtherEquipments([]);
            return;
          }
          if (json.spreadsheetUrl && json.spreadsheetUrl.trim()) {
            const clean = json.spreadsheetUrl.trim();
            try {
              for (const k of [activeTenant, activeTenant.toUpperCase(), activeTenant.toLowerCase()]) {
                localStorage.setItem(`defib_${k}_spreadsheet_autres_materiels`, clean);
              }
            } catch (_) {}
            setCompanyInfo(prev => ({
              ...prev,
              spreadsheetAutresMateriels: clean,
              spreadsheetAutresMaterielsUrl: clean,
            }));
          }
          setOtherEquipments(
            firstItems.filter(
              (eq: any) =>
                eq &&
                !String(eq.id || '').startsWith('sheet_am_') &&
                !String(eq.identifiant || '').startsWith('sheet_am_')
            )
          );
        },
        (allItems) => {
          setOtherEquipments(
            allItems.filter(
              (eq: any) =>
                eq &&
                !String(eq.id || '').startsWith('sheet_am_') &&
                !String(eq.identifiant || '').startsWith('sheet_am_')
            )
          );
        }
      );
    } catch (err) {
      console.warn('Manual refresh Autres Matériels error:', err);
    } finally {
      setTimeout(() => {
        setIsRefreshingAutresMateriels(false);
      }, 500);
    }
  };

  const handleManualRefreshClients = async () => {
    setIsRefreshingClients(true);
    try {
      const activeTenant = tenantId || 'demo';
      const urlClients =
        companyInfo?.spreadsheetClients ||
        companyInfo?.spreadsheetClientsUrl ||
        localStorage.getItem(`defib_${activeTenant}_spreadsheet_clients`) ||
        localStorage.getItem(`defib_${activeTenant.toUpperCase()}_spreadsheet_clients`) ||
        localStorage.getItem(`defib_${activeTenant.toLowerCase()}_spreadsheet_clients`) ||
        '';

      await fetchSheetCollectionInBatches(
        activeTenant,
        'clients',
        urlClients,
        true,
        (json, firstItems) => {
          if (!json.fromSpreadsheet || json.status === 'no_spreadsheet') {
            setClients([]);
            idbSet(`defib_${activeTenant}_clients`, []).catch(() => {});
            return;
          }
          if (json.spreadsheetUrl && json.spreadsheetUrl.trim()) {
            const clean = json.spreadsheetUrl.trim();
            try {
              for (const k of [activeTenant, activeTenant.toUpperCase(), activeTenant.toLowerCase()]) {
                localStorage.setItem(`defib_${k}_spreadsheet_clients`, clean);
              }
            } catch (_) {}
            setCompanyInfo(prev => ({
              ...prev,
              spreadsheetClients: clean,
              spreadsheetClientsUrl: clean,
            }));
          }
          if (json.stats?.clientVolumes) {
            setDefibSheetStats(prev => (prev ? { ...prev, clientVolumes: json.stats.clientVolumes } : json.stats));
          }
          const validFirst = firstItems.filter(
            (cl: any) =>
              cl &&
              !String(cl.id || '').startsWith('sheet_cli_') &&
              !String(cl.clientIdField || '').startsWith('sheet_cli_')
          );
          setClients(validFirst);
          idbSet(`defib_${activeTenant}_clients_v2`, validFirst).catch(() => {});
        },
        (allItems) => {
          const validAll = allItems.filter(
            (cl: any) =>
              cl &&
              !String(cl.id || '').startsWith('sheet_cli_') &&
              !String(cl.clientIdField || '').startsWith('sheet_cli_')
          );
          setClients(validAll);
          idbSet(`defib_${activeTenant}_clients_v2`, validAll).catch(() => {});
        }
      );
    } catch (err) {
      console.warn('Manual refresh Clients error:', err);
    } finally {
      setTimeout(() => {
        setIsRefreshingClients(false);
      }, 500);
    }
  };

  const lastLoadedSheetUrlsRef = React.useRef<{ tenant: string; defibs: string; autres: string; clients: string }>({
    tenant: '',
    defibs: '',
    autres: '',
    clients: '',
  });
  const activeSheetBatchRunRef = React.useRef<{
    tenant: string;
    defibsRunId: number;
    defibsInFlightUrl: string;
    autresRunId: number;
    autresInFlightUrl: string;
    clientsRunId: number;
    clientsInFlightUrl: string;
  }>({
    tenant: '',
    defibsRunId: 0,
    defibsInFlightUrl: '',
    autresRunId: 0,
    autresInFlightUrl: '',
    clientsRunId: 0,
    clientsInFlightUrl: '',
  });

  // Automatic Google Spreadsheets sync for Défibrillateurs, Autres Matériels, and Clients whenever URLs are configured or updated
  useEffect(() => {
    if (
      !isLoggedIn ||
      !tenantId ||
      tenantId.toLowerCase() === 'megaadmin' ||
      localStorage.getItem('defib_logged_user_role') === 'megaadmin' ||
      !isFirebaseLoaded ||
      loadedTenantIdState !== tenantId
    )
      return;

    const sanitizeSheetUrl = (u?: string | null): string => {
      if (!u || typeof u !== 'string') return '';
      const trimmed = u.trim();
      if (trimmed.includes('1tB1e41') || trimmed.includes('2mX5O6r9hD0i3Z9m')) return '';
      return trimmed;
    };

    const loadSpreadsheetsForTenant = async (customInfo?: Partial<CompanyInfo>, force = false) => {
      const activeTid = tenantId || 'demo';
      const urlDefibs =
        sanitizeSheetUrl(customInfo?.spreadsheetDefibrillateurs) ||
        sanitizeSheetUrl(companyInfo?.spreadsheetDefibrillateurs) ||
        sanitizeSheetUrl(localStorage.getItem(`defib_${activeTid}_spreadsheet_defibrillateurs`)) ||
        sanitizeSheetUrl(localStorage.getItem(`defib_${activeTid.toUpperCase()}_spreadsheet_defibrillateurs`)) ||
        sanitizeSheetUrl(localStorage.getItem(`defib_${activeTid.toLowerCase()}_spreadsheet_defibrillateurs`)) ||
        '';
      const urlAutres =
        sanitizeSheetUrl(customInfo?.spreadsheetAutresMateriels) ||
        sanitizeSheetUrl(companyInfo?.spreadsheetAutresMateriels) ||
        sanitizeSheetUrl(localStorage.getItem(`defib_${activeTid}_spreadsheet_autres_materiels`)) ||
        sanitizeSheetUrl(localStorage.getItem(`defib_${activeTid.toUpperCase()}_spreadsheet_autres_materiels`)) ||
        sanitizeSheetUrl(localStorage.getItem(`defib_${activeTid.toLowerCase()}_spreadsheet_autres_materiels`)) ||
        '';
      const urlClients =
        sanitizeSheetUrl(customInfo?.spreadsheetClients) ||
        sanitizeSheetUrl(companyInfo?.spreadsheetClients) ||
        sanitizeSheetUrl(localStorage.getItem(`defib_${activeTid}_spreadsheet_clients`)) ||
        sanitizeSheetUrl(localStorage.getItem(`defib_${activeTid.toUpperCase()}_spreadsheet_clients`)) ||
        sanitizeSheetUrl(localStorage.getItem(`defib_${activeTid.toLowerCase()}_spreadsheet_clients`)) ||
        '';

      // Avoid redundant re-fetching or aborting an already-running multi-batch load when background companyInfo sync resolves the same URL
      const prevLoaded = lastLoadedSheetUrlsRef.current;
      const batchState = activeSheetBatchRunRef.current;
      const isSameTenant = prevLoaded.tenant.toLowerCase() === activeTid.toLowerCase();

      if (batchState.tenant.toLowerCase() !== activeTid.toLowerCase()) {
        batchState.tenant = activeTid;
        batchState.defibsRunId++;
        batchState.defibsInFlightUrl = '';
        batchState.autresRunId++;
        batchState.autresInFlightUrl = '';
        batchState.clientsRunId++;
        batchState.clientsInFlightUrl = '';
      }

      const defibsAlreadyInFlight =
        !force &&
        Boolean(batchState.defibsInFlightUrl) &&
        (!urlDefibs || batchState.defibsInFlightUrl === urlDefibs || batchState.defibsInFlightUrl === '__auto__');
      const autresAlreadyInFlight =
        !force &&
        Boolean(batchState.autresInFlightUrl) &&
        (!urlAutres || batchState.autresInFlightUrl === urlAutres || batchState.autresInFlightUrl === '__auto__');
      const clientsAlreadyInFlight =
        !force &&
        Boolean(batchState.clientsInFlightUrl) &&
        (!urlClients || batchState.clientsInFlightUrl === urlClients || batchState.clientsInFlightUrl === '__auto__');

      const expectedMinDefibs = Math.max(1, (defibSheetStats?.totalCount || 0) - 50);
      const skipDefibs =
        defibsAlreadyInFlight ||
        (!force &&
          defibrillateurs.length >= expectedMinDefibs &&
          isSameTenant &&
          Boolean(prevLoaded.defibs) &&
          (!urlDefibs || prevLoaded.defibs === urlDefibs));
      const skipAutres =
        autresAlreadyInFlight ||
        (!force &&
          otherEquipments.length > 0 &&
          isSameTenant &&
          Boolean(prevLoaded.autres) &&
          (!urlAutres || prevLoaded.autres === urlAutres));
      const skipClients =
        clientsAlreadyInFlight ||
        (!force &&
          clients.length > 0 &&
          isSameTenant &&
          Boolean(prevLoaded.clients) &&
          (!urlClients || prevLoaded.clients === urlClients));

      if (skipDefibs && skipAutres && skipClients) {
        return;
      }

      if (!isSameTenant) {
        lastLoadedSheetUrlsRef.current = { tenant: activeTid, defibs: '', autres: '', clients: '' };
      }

      const delSet = new Set(getDeletedDefibKeys(activeTid));

      const persistResolvedUrl = (
        field: 'spreadsheetDefibrillateurs' | 'spreadsheetAutresMateriels' | 'spreadsheetClients',
        localKeySuffix: string,
        resolvedUrl?: string,
        markFullyLoaded = false
      ) => {
        const clean = sanitizeSheetUrl(resolvedUrl);
        if (!clean) return;
        if (markFullyLoaded) {
          if (field === 'spreadsheetDefibrillateurs') lastLoadedSheetUrlsRef.current.defibs = clean;
          if (field === 'spreadsheetAutresMateriels') lastLoadedSheetUrlsRef.current.autres = clean;
          if (field === 'spreadsheetClients') lastLoadedSheetUrlsRef.current.clients = clean;
        }
        try {
          for (const k of [activeTid, activeTid.toUpperCase(), activeTid.toLowerCase()]) {
            localStorage.setItem(`defib_${k}_${localKeySuffix}`, clean);
          }
        } catch (_) {}
        if (markFullyLoaded) {
          setCompanyInfo(prev => {
            if (prev[field] === clean) return prev;
            const updated = {
              ...prev,
              [field]: clean,
              [`${field}Url`]: clean,
            };
            try {
              localStorage.setItem(`defib_${activeTid}_company_info`, JSON.stringify(updated));
            } catch (_) {}
            return updated;
          });
        }
      };

      await Promise.all([
        (async () => {
          if (skipDefibs) return;
          const myRunId = ++batchState.defibsRunId;
          batchState.defibsInFlightUrl = urlDefibs || '__auto__';
          try {
            let resolvedDefibSheetUrl = urlDefibs;
            await fetchSheetCollectionInBatches(
              activeTid,
              'defibrillateurs',
              urlDefibs,
              force,
              (json, firstItems) => {
                if (!json.fromSpreadsheet || json.status === 'no_spreadsheet') {
                  batchState.defibsInFlightUrl = '';
                  setDefibrillateurs([]);
                  setDefibSheetStats(null);
                  idbSet(`defib_${activeTid}_defibrillateurs_v110`, []).catch(() => {});
                  setIsDefibLoading(false);
                  return;
                }
                if (json.spreadsheetUrl) {
                  resolvedDefibSheetUrl = json.spreadsheetUrl;
                  batchState.defibsInFlightUrl = sanitizeSheetUrl(json.spreadsheetUrl) || urlDefibs || '__auto__';
                  persistResolvedUrl('spreadsheetDefibrillateurs', 'spreadsheet_defibrillateurs', json.spreadsheetUrl, !json.hasMore);
                }
                const filtered = firstItems.filter((df: any) => !isDefibInDeletedList(df, delSet));
                setDefibrillateurs(filtered);
                if (filtered.length > 0) {
                  persistDefibCache(activeTid, filtered, json.stats);
                } else if (json.stats) {
                  setDefibSheetStats(json.stats);
                }
                const tot = json.totalCount || filtered.length;
                setDefibLoadingProgress({
                  current: filtered.length,
                  total: tot,
                  percent: tot > 0 ? Math.min(100, Math.round((filtered.length / tot) * 100)) : 100,
                  message: `Chargement ${filtered.length.toLocaleString('en-US')}/${tot.toLocaleString('en-US')}...`,
                });
                setIsDefibLoading(false);
              },
              (allItems, loadedCount, totalCount, batchJson) => {
                const filtered = allItems.filter((df: any) => !isDefibInDeletedList(df, delSet));
                if (filtered.length > 0) {
                  setDefibrillateurs(filtered);
                  persistDefibCache(activeTid, filtered, batchJson?.stats);
                }
                const tot = totalCount || filtered.length;
                setDefibLoadingProgress({
                  current: filtered.length,
                  total: tot,
                  percent: tot > 0 ? Math.min(100, Math.round((filtered.length / tot) * 100)) : 100,
                  message: loadedCount >= tot
                    ? `Chargement ${filtered.length.toLocaleString('en-US')}/${tot.toLocaleString('en-US')}, Terminé.`
                    : `Chargement ${filtered.length.toLocaleString('en-US')}/${tot.toLocaleString('en-US')}...`,
                });
                if (loadedCount >= totalCount && resolvedDefibSheetUrl) {
                  persistResolvedUrl('spreadsheetDefibrillateurs', 'spreadsheet_defibrillateurs', resolvedDefibSheetUrl, true);
                }
              },
              () => batchState.defibsRunId !== myRunId || batchState.tenant.toLowerCase() !== activeTid.toLowerCase()
            );
          } catch (_) {
            if (batchState.defibsRunId === myRunId) setIsDefibLoading(false);
          } finally {
            if (batchState.defibsRunId === myRunId) {
              batchState.defibsInFlightUrl = '';
            }
          }
        })(),
        (async () => {
          if (skipAutres) return;
          const myRunId = ++batchState.autresRunId;
          batchState.autresInFlightUrl = urlAutres || '__auto__';
          try {
            let resolvedAutresUrl = urlAutres;
            await fetchSheetCollectionInBatches(
              activeTid,
              'autresMateriels',
              urlAutres,
              force,
              (json, firstItems) => {
                if (!json.fromSpreadsheet || json.status === 'no_spreadsheet') {
                  batchState.autresInFlightUrl = '';
                  setOtherEquipments([]);
                  return;
                }
                if (json.spreadsheetUrl) {
                  resolvedAutresUrl = json.spreadsheetUrl;
                  batchState.autresInFlightUrl = sanitizeSheetUrl(json.spreadsheetUrl) || urlAutres || '__auto__';
                  persistResolvedUrl('spreadsheetAutresMateriels', 'spreadsheet_autres_materiels', json.spreadsheetUrl, !json.hasMore);
                }
                const filtered = firstItems.filter(
                  (eq: any) =>
                    eq &&
                    !String(eq.id || '').startsWith('sheet_am_') &&
                    !String(eq.identifiant || '').startsWith('sheet_am_')
                );
                setOtherEquipments(filtered);
              },
              (allItems, loadedCount, totalCount) => {
                const filtered = allItems.filter(
                  (eq: any) =>
                    eq &&
                    !String(eq.id || '').startsWith('sheet_am_') &&
                    !String(eq.identifiant || '').startsWith('sheet_am_')
                );
                setOtherEquipments(filtered);
                if (loadedCount >= totalCount && resolvedAutresUrl) {
                  persistResolvedUrl('spreadsheetAutresMateriels', 'spreadsheet_autres_materiels', resolvedAutresUrl, true);
                }
              },
              () => batchState.autresRunId !== myRunId || batchState.tenant.toLowerCase() !== activeTid.toLowerCase()
            );
          } catch (_) {} finally {
            if (batchState.autresRunId === myRunId) {
              batchState.autresInFlightUrl = '';
            }
          }
        })(),
        (async () => {
          if (skipClients) return;
          const myRunId = ++batchState.clientsRunId;
          batchState.clientsInFlightUrl = urlClients || '__auto__';
          try {
            let resolvedClientsUrl = urlClients;
            await fetchSheetCollectionInBatches(
              activeTid,
              'clients',
              urlClients,
              force,
              (json, firstItems) => {
                if (!json.fromSpreadsheet || json.status === 'no_spreadsheet') {
                  batchState.clientsInFlightUrl = '';
                  setClients([]);
                  idbSet(`defib_${activeTid}_clients`, []).catch(() => {});
                  return;
                }
                if (json.spreadsheetUrl) {
                  resolvedClientsUrl = json.spreadsheetUrl;
                  batchState.clientsInFlightUrl = sanitizeSheetUrl(json.spreadsheetUrl) || urlClients || '__auto__';
                  persistResolvedUrl('spreadsheetClients', 'spreadsheet_clients', json.spreadsheetUrl, !json.hasMore);
                }
                if (json.stats?.clientVolumes) {
                  setDefibSheetStats(prev =>
                    prev && typeof prev.totalMainNon === 'number'
                      ? { ...prev, clientVolumes: json.stats.clientVolumes }
                      : json.stats.totalMainNon > 0
                        ? json.stats
                        : { clientVolumes: json.stats.clientVolumes }
                  );
                }
                const filtered = firstItems.filter(
                  (cl: any) =>
                    cl &&
                    !String(cl.id || '').startsWith('sheet_cli_') &&
                    !String(cl.clientIdField || '').startsWith('sheet_cli_')
                );
                lastLoadedSheetUrlsRef.current.clients = json.spreadsheetUrl || urlClients || 'loaded';
                idbSet(`defib_${activeTid}_clients_v2`, filtered).catch(() => {});
                setClients(filtered);
              },
              (allItems, loadedCount, totalCount) => {
                const filtered = allItems.filter(
                  (cl: any) =>
                    cl &&
                    !String(cl.id || '').startsWith('sheet_cli_') &&
                    !String(cl.clientIdField || '').startsWith('sheet_cli_')
                );
                idbSet(`defib_${activeTid}_clients_v2`, filtered).catch(() => {});
                setClients(filtered);
                if (loadedCount >= totalCount && resolvedClientsUrl) {
                  persistResolvedUrl('spreadsheetClients', 'spreadsheet_clients', resolvedClientsUrl, true);
                }
              },
              () => batchState.clientsRunId !== myRunId || batchState.tenant.toLowerCase() !== activeTid.toLowerCase()
            );
          } catch (_) {} finally {
            if (batchState.clientsRunId === myRunId) {
              batchState.clientsInFlightUrl = '';
            }
          }
        })(),
      ]);
    };

    loadSpreadsheetsForTenant(undefined, false);

    const handleUpdatedEvent = (e: Event) => {
      const detail = (e as CustomEvent)?.detail;
      loadSpreadsheetsForTenant(detail, true);
    };
    window.addEventListener('defib-tenant-spreadsheets-updated', handleUpdatedEvent);
    return () => {
      window.removeEventListener('defib-tenant-spreadsheets-updated', handleUpdatedEvent);
    };
  }, [
    isLoggedIn,
    tenantId,
    isFirebaseLoaded,
    loadedTenantIdState,
    companyInfo?.spreadsheetDefibrillateurs,
    companyInfo?.spreadsheetAutresMateriels,
    companyInfo?.spreadsheetClients,
  ]);

  // High-availability deleted-keys sync across multi-PC sessions (never wipes or reloads table display)
  useEffect(() => {
    if (!isLoggedIn || !tenantId) return;
    const tAliases = getTenantAliases(tenantId);
    const isChunkedTenant = tAliases.has('d27') || tAliases.has('d58');
    if (!isChunkedTenant) return;

    let isCancelled = false;

    const syncDeletedKeysOnly = async () => {
      try {
        if (isCancelled) return;
        const remoteKeys = await fetchRemoteDeletedDefibKeys(tenantId);
        if (remoteKeys.length > 0 && !isCancelled) {
          const localKeys = getDeletedDefibKeys(tenantId);
          const combined = Array.from(new Set([...localKeys, ...remoteKeys]));
          localStorage.setItem(`defib_${tenantId}_deleted_defib_keys`, JSON.stringify(combined));
          const delSet = new Set(combined);
          setDefibrillateurs(prev => {
            if (!Array.isArray(prev) || prev.length === 0) return prev;
            const filtered = prev.filter(df => !isDefibInDeletedList(df, delSet));
            return filtered.length !== prev.length ? filtered : prev;
          });
        }
      } catch (_) {}
    };

    syncDeletedKeysOnly();
    const intervalId = setInterval(syncDeletedKeysOnly, 30000);

    return () => {
      isCancelled = true;
      clearInterval(intervalId);
    };
  }, [tenantId]);

  companyInfoRef.current = companyInfo;
  useEffect(() => {
    companyInfoRef.current = companyInfo;
  }, [companyInfo]);

  const getTenantTourPrefix = useCallback((tid?: string): string => {
    const clean = (tid || tenantId || '').trim();
    if (!clean || clean.toLowerCase() === 'demo') {
      return 'D18';
    }
    if (typeof window !== 'undefined') {
      try {
        const cachedRaw = localStorage.getItem('fs_cache_registered_tenants');
        if (cachedRaw) {
          const cachedTenants = JSON.parse(cachedRaw);
          if (Array.isArray(cachedTenants)) {
            const matchedCached = findTenantInList(cachedTenants, clean) as any;
            if (matchedCached?.shortEnvId) {
              return String(matchedCached.shortEnvId).trim().toUpperCase();
            }
          }
        }
      } catch (_) {}
    }
    const matchedKnown = findTenantInList(KNOWN_TENANTS_REGISTRY as any[], clean) as any;
    if (matchedKnown?.shortEnvId) {
      return String(matchedKnown.shortEnvId).trim().toUpperCase();
    }
    if (!tid || clean.toLowerCase() === (tenantId || '').trim().toLowerCase()) {
      const storedShort = (typeof window !== 'undefined' ? localStorage.getItem('defib_short_env_id') : null) || shortEnvId;
      if (storedShort && storedShort.trim()) {
        return storedShort.trim().toUpperCase();
      }
    }
    return 'D18';
  }, [tenantId, shortEnvId]);

  const ensureFsmTourIdentifiers = useCallback((toursList: any[], activeTid?: string): { tours: any[]; changed: boolean } => {
    if (!Array.isArray(toursList) || toursList.length === 0) {
      return { tours: toursList || [], changed: false };
    }
    const prefix = getTenantTourPrefix(activeTid || tenantId);
    const seqRegex = new RegExp(`^(?:([A-Z0-9_-]+)-)?TOUR-(\\d{1,})$`, 'i');
    let maxSeq = 0;
    try {
      const savedSeq = parseInt(localStorage.getItem(`defib_${prefix}_tour_last_seq`) || '0', 10);
      if (!isNaN(savedSeq) && savedSeq > maxSeq) maxSeq = savedSeq;
    } catch (_) {}

    let prefixUpdated = false;
    const normalizedList = toursList.map((t) => {
      if (!t || t.id === 'a-trier') return t;
      const existingId = String(t.tourIdentifiant || t.identifiant || '').trim();
      const match = existingId.match(seqRegex);
      if (match) {
        const num = parseInt(match[2], 10);
        if (!isNaN(num) && num > maxSeq) maxSeq = num;
        const paddedNum = String(num).padStart(4, '0');
        const targetId = `${prefix}-TOUR-${paddedNum}`;
        if (!match[1] || match[1].toUpperCase() !== prefix.toUpperCase() || t.tourIdentifiant !== targetId) {
          prefixUpdated = true;
          return {
            ...t,
            tourIdentifiant: targetId
          };
        }
      }
      return t;
    });

    // Assign missing identifiers from oldest to newest (bottom to top since new tours are prepended)
    const indicesNeedingId: number[] = [];
    normalizedList.forEach((t, idx) => {
      if (!t || t.id === 'a-trier') return;
      const existingId = String(t.tourIdentifiant || '').trim();
      if (!seqRegex.test(existingId)) {
        indicesNeedingId.push(idx);
      }
    });

    if (indicesNeedingId.length === 0) {
      return { tours: normalizedList, changed: prefixUpdated };
    }

    const updated = [...normalizedList];
    for (let i = indicesNeedingId.length - 1; i >= 0; i--) {
      const idx = indicesNeedingId[i];
      maxSeq += 1;
      const frozenId = `${prefix}-TOUR-${String(maxSeq).padStart(4, '0')}`;
      updated[idx] = {
        ...updated[idx],
        tourIdentifiant: frozenId
      };
    }

    try {
      localStorage.setItem(`defib_${prefix}_tour_last_seq`, String(maxSeq));
    } catch (_) {}

    return { tours: updated, changed: true };
  }, [getTenantTourPrefix, tenantId]);

  const refreshGenericSheetCompartment = useCallback(
    async (
      tabType: string,
      forceRefresh = false,
      tenantIdOverride?: string,
      spreadsheetUrlOverride?: string
    ) => {
      const activeTid =
        tenantIdOverride ||
        tenantId ||
        localStorage.getItem('defib_tenant_id') ||
        'demo';
      const currentCompanyInfo = companyInfoRef.current;

      const tabToFieldKeyMap: Record<string, any> = {
        tournees: 'spreadsheetTournees',
        missionsTournees: 'spreadsheetMissionsTournees',
        rapportsPdf: 'spreadsheetRapportsPdf',
        crm: 'spreadsheetCrm',
        reglagesCrm: 'spreadsheetReglagesCrm',
        satisfaction: 'spreadsheetSatisfaction',
        commandes: 'spreadsheetCommandes',
        devisFactures: 'spreadsheetCommandes',
        stocksGlobaux: 'spreadsheetStocks',
        stocksDistribues: 'spreadsheetStocksDistribues',
        historiqueNotifications: 'spreadsheetStocks',
        achatsFournisseurs: 'spreadsheetAchatsFournisseurs',
        temps: 'spreadsheetTemps',
        ticketsCaisse: 'spreadsheetTicketsCaisse',
        releveConcurrentiel: 'spreadsheetReleveConcurrentiel',
        formations: 'spreadsheetFormations',
        stagiaires: 'spreadsheetStagiaires',
        emargements: 'spreadsheetEmargements',
        messagesInternes: 'spreadsheetMessagesInternes',
        variables: 'spreadsheetVariables',
        ged: 'spreadsheetGed',
        intituleEmplacements: 'spreadsheetIntituleEmplacements',
        membresEnvironnement: 'spreadsheetMembresEnvironnement',
        reglages: 'spreadsheetReglages',
        apparenceRapportsPdf: 'spreadsheetApparenceRapportsPdf',
        communicationPortailClient: 'spreadsheetCommunicationPortailClient',
        observateurActionsSuspectes: 'spreadsheetObservateurActionsSuspectes',
      };

      const persistSecondarySpreadsheetUrl = (fieldKey: string, resolvedUrl?: string) => {
        const clean = resolvedUrl ? String(resolvedUrl).trim() : '';
        if (!clean || clean.includes('1tB1e41') || clean.includes('2mX5O6r9hD0i3Z9m')) return;
        const def = EXTRA_SPREADSHEET_FIELDS.find(f => f.key === fieldKey || f.urlKey === fieldKey);
        if (def) {
          for (const k of [activeTid, activeTid.toUpperCase(), activeTid.toLowerCase()]) {
            safeSetLocalStorage(`defib_${k}_${def.storageSuffix}`, clean);
          }
        }
        setCompanyInfo(prev => {
          if ((prev as any)?.[fieldKey] === clean) return prev;
          const updated = {
            ...prev,
            [fieldKey]: clean,
            [`${fieldKey}Url`]: clean,
          };
          safeSetLocalStorage(`defib_${activeTid}_company_info`, JSON.stringify(updated));
          return updated;
        });
      };

      const clearCompartmentState = (tt: string) => {
        switch (tt) {
          case 'tournees':
          case 'missionsTournees':
            setFsmTours([]);
            try { localStorage.removeItem(`defib_${activeTid}_fsm_tours`); } catch (_) {}
            break;
          case 'rapportsPdf':
            setGeneratedReports([]);
            try { localStorage.removeItem(`defib_${activeTid}_generated_reports`); } catch (_) {}
            break;
          case 'crm':
            setTickets([]);
            try { localStorage.removeItem(`defib_${activeTid}_support_tickets`); } catch (_) {}
            break;
          case 'satisfaction':
            setCustomerReviews([]);
            try { localStorage.removeItem(`defib_${activeTid}_customer_reviews`); } catch (_) {}
            break;
          case 'commandes':
          case 'devisFactures':
            setCommercialDocs([]);
            try { localStorage.removeItem(`defib_${activeTid}_commercial_docs`); } catch (_) {}
            break;
          case 'stocksGlobaux':
            setStocks([]);
            try { localStorage.removeItem(`defib_${activeTid}_stocks`); } catch (_) {}
            break;
          case 'stocksDistribues':
            setDistributedStocks([]);
            try { localStorage.removeItem(`defib_${activeTid}_distributed_stocks`); } catch (_) {}
            break;
          case 'historiqueNotifications':
            setLogisticsNotifications([]);
            try { localStorage.removeItem(`defib_${activeTid}_logistics_notifications`); } catch (_) {}
            break;
          case 'achatsFournisseurs':
            setAchatsFournisseurs([]);
            try { localStorage.removeItem(`defib_${activeTid}_achats_fournisseurs`); } catch (_) {}
            break;
          case 'temps':
            setPointages([]);
            try { localStorage.removeItem(`defib_${activeTid}_pointages_history`); } catch (_) {}
            break;
          case 'ticketsCaisse':
            setExpenses([]);
            try { localStorage.removeItem(`defib_${activeTid}_expenses`); } catch (_) {}
            break;
          case 'releveConcurrentiel':
            setVeilles([]);
            try { localStorage.removeItem(`defib_${activeTid}_veilles`); } catch (_) {}
            break;
          case 'formations':
            setFormations([]);
            try { localStorage.removeItem(`defib_${activeTid}_formations`); } catch (_) {}
            break;
          case 'stagiaires':
            setStagiaires([]);
            try { localStorage.removeItem(`defib_${activeTid}_stagiaires`); } catch (_) {}
            break;
          case 'emargements':
            setEmargements([]);
            try { localStorage.removeItem(`defib_${activeTid}_emargements`); } catch (_) {}
            break;
          case 'messagesInternes':
            setTenantMessages([]);
            try { localStorage.removeItem(`defib_${activeTid}_tenant_messages`); } catch (_) {}
            break;
          case 'variables':
            setVariables([]);
            try { localStorage.removeItem(`defib_${activeTid}_variables`); } catch (_) {}
            break;
          case 'ged':
            setGedDocs([]);
            try { localStorage.removeItem(`defib_${activeTid}_ged_docs`); } catch (_) {}
            break;
          case 'observateurActionsSuspectes':
            setSuspiciousActivityLogs([]);
            try { localStorage.removeItem(`defib_${activeTid}_suspicious_activity_logs`); } catch (_) {}
            break;
          default:
            break;
        }
      };

      try {
        if (tabType === 'tournees' || tabType === 'missionsTournees') {
          const tourneesUrl =
            (tabType === 'tournees' && spreadsheetUrlOverride) ||
            getTenantSpreadsheetUrl('spreadsheetTournees', currentCompanyInfo);
          const missionsUrl =
            (tabType === 'missionsTournees' && spreadsheetUrlOverride) ||
            getTenantSpreadsheetUrl('spreadsheetMissionsTournees', currentCompanyInfo);
          const [resTours, resMissions] = await Promise.all([
            fetch(
              `/api/sheets/collection?tenantId=${encodeURIComponent(activeTid)}&type=tournees&refresh=${forceRefresh}${
                tourneesUrl ? `&spreadsheetUrl=${encodeURIComponent(tourneesUrl)}` : ''
              }`
            ).catch(() => null),
            fetch(
              `/api/sheets/collection?tenantId=${encodeURIComponent(activeTid)}&type=missionsTournees&refresh=${forceRefresh}${
                missionsUrl ? `&spreadsheetUrl=${encodeURIComponent(missionsUrl)}` : ''
              }`
            ).catch(() => null),
          ]);
          const dataTours = resTours && resTours.ok ? await resTours.json().catch(() => null) : null;
          const dataMissions = resMissions && resMissions.ok ? await resMissions.json().catch(() => null) : null;

          // If both network requests failed transiently, maintain current state instead of wiping
          if (!dataTours && !dataMissions) {
            return;
          }

          if (dataTours?.spreadsheetUrl) {
            persistSecondarySpreadsheetUrl('spreadsheetTournees', dataTours.spreadsheetUrl);
          }
          if (dataMissions?.spreadsheetUrl) {
            persistSecondarySpreadsheetUrl('spreadsheetMissionsTournees', dataMissions.spreadsheetUrl);
          }

          const hasToursFromSheet = Boolean(dataTours?.fromSpreadsheet && Array.isArray(dataTours.items));
          const hasMissionsFromSheet = Boolean(dataMissions?.fromSpreadsheet && Array.isArray(dataMissions.items));
          if (!hasToursFromSheet && !hasMissionsFromSheet) {
            if (
              dataTours?.status === 'no_spreadsheet' &&
              dataMissions?.status === 'no_spreadsheet' &&
              !tourneesUrl &&
              !missionsUrl
            ) {
              clearCompartmentState('tournees');
            }
            return;
          }

          const sheetTours: any[] = hasToursFromSheet ? dataTours.items : [];
          const sheetMissions: any[] = hasMissionsFromSheet ? dataMissions.items : [];

          const rawBaseTours: any[] = [
            {
              id: 'a-trier',
              name: 'Missions à trier',
              title: 'Missions à trier',
              date: '-',
              startDate: 'A trier',
              techName: 'Non assigné',
              vehicule: '-',
              status: 'En attente',
              totalDistance: '-',
              totalDuration: '-',
              co2Saved: '-',
              missions: [],
            },
            ...sheetTours.map((st: any, idx: number) => {
              const rawSt = String(st.status || st.statut || st.situation || 'Brouillon')
                .trim()
                .normalize('NFD')
                .replace(/[\u0300-\u036f]/g, '')
                .toLowerCase();
              const normStatus =
                rawSt === 'a faire' || rawSt === 'afaire'
                  ? 'À faire'
                  : rawSt === 'en cours' || rawSt === 'encours'
                  ? 'En cours'
                  : rawSt === 'termine' || rawSt === 'terminee'
                  ? 'Terminé'
                  : rawSt === 'effectue' || rawSt === 'effectuee'
                  ? 'Effectué'
                  : 'Brouillon';
              return {
                ...st,
                id: st.id || st.tourIdentifiant || `tour-${idx + 1}`,
                tourIdentifiant: st.tourIdentifiant || st.id || `TOUR-${String(idx + 1).padStart(4, '0')}`,
                title: st.title || st.name || 'Tournée',
                name: st.name || st.title || 'Tournée',
                startDate: st.startDate || st.date || '',
                date: st.date || st.startDate || '',
                techName: st.techName || 'Non assigné',
                plannerName: st.plannerName || st.planificateur || '',
                region: st.region || st.departement || '',
                vehicule: st.vehicule || '-',
                status: normStatus,
                missions: Array.isArray(st.missions) ? [...st.missions] : [],
              };
            }),
          ];

          const { tours: baseTours } = ensureFsmTourIdentifiers(rawBaseTours, activeTid);

          if (sheetMissions.length > 0) {
            const byTourKey = new Map<string, any[]>();
            const extractTourNum = (s: string) => {
              const m = String(s || '').match(/TOUR-(\d+)$/i);
              return m ? parseInt(m[1], 10) : null;
            };
            for (const sm of sheetMissions) {
              if (!sm || typeof sm !== 'object') continue;
              const tid = String(sm.tourIdentifiant || sm.tourId || '').trim();
              const tidLower = tid.toLowerCase();
              const tidNum = extractTourNum(tid);
              const matchedTour = tid
                ? baseTours.find((bt: any) => {
                    if (bt.id === 'a-trier') return false;
                    const btIdent = String(bt.tourIdentifiant || '').trim().toLowerCase();
                    const btId = String(bt.id || '').trim().toLowerCase();
                    const btTitle = String(bt.title || bt.name || '').trim().toLowerCase();
                    if (btIdent === tidLower || btId === tidLower || btTitle === tidLower) return true;
                    if (tidNum !== null) {
                      const btNum = extractTourNum(btIdent) ?? extractTourNum(btId);
                      if (btNum !== null && btNum === tidNum) return true;
                    }
                    return false;
                  })
                : null;
              const targetTourId = matchedTour ? matchedTour.id : 'a-trier';
              const list = byTourKey.get(targetTourId) || [];
              const rawRef = String(sm.interventionReference || '').trim();
              const cleanRef =
                rawRef && !rawRef.startsWith('fsm-m-')
                  ? rawRef
                  : `INT-2026-${String(rawRef || sm.id || Date.now()).replace(/\D/g, '').slice(-5).padStart(5, '0')}`;
              const cleanDefibId = String(
                sm.defibIdentifiant || (!String(sm.identifiant || '').startsWith('fsm-m-') ? sm.identifiant : '') || ''
              ).trim();
              list.push({
                ...sm,
                id: sm.id || cleanRef || `fsm-m-${Date.now()}-${list.length}`,
                interventionReference: cleanRef,
                defibIdentifiant: cleanDefibId || sm.defibIdentifiant || '',
              });
              byTourKey.set(targetTourId, list);
            }

            const mergedTours = baseTours.map((bt: any) => {
              const assignedFromSheet = byTourKey.get(bt.id) || [];
              return {
                ...bt,
                missions: assignedFromSheet.length > 0 ? assignedFromSheet : (Array.isArray(bt.missions) ? bt.missions : []),
              };
            });
            setFsmTours(mergedTours);
            safeSetLocalStorage(`defib_${activeTid}_fsm_tours`, JSON.stringify(mergedTours));
            return;
          }

          if (sheetTours.length === 0 && sheetMissions.length === 0) {
            setFsmTours(prev => (prev.length === 0 ? [] : baseTours));
            safeSetLocalStorage(`defib_${activeTid}_fsm_tours`, JSON.stringify(baseTours));
            return;
          }

          setFsmTours(baseTours);
          safeSetLocalStorage(`defib_${activeTid}_fsm_tours`, JSON.stringify(baseTours));
          return;
        }

        const fieldKey = tabToFieldKeyMap[tabType];
        const clientSheetUrl =
          spreadsheetUrlOverride ||
          (fieldKey ? getTenantSpreadsheetUrl(fieldKey, currentCompanyInfo) : '');
        const res = await fetch(
          `/api/sheets/collection?tenantId=${encodeURIComponent(activeTid)}&type=${encodeURIComponent(tabType)}&refresh=${forceRefresh}${
            clientSheetUrl ? `&spreadsheetUrl=${encodeURIComponent(clientSheetUrl)}` : ''
          }`
        ).catch(() => null);
        if (!res || !res.ok) {
          return;
        }
        const data = await res.json().catch(() => null);
        if (!data) {
          return;
        }
        if (data.spreadsheetUrl && fieldKey) {
          persistSecondarySpreadsheetUrl(fieldKey, data.spreadsheetUrl);
        }
        if (!data?.fromSpreadsheet || !Array.isArray(data.items)) {
          if (data?.status === 'no_spreadsheet' && !clientSheetUrl) {
            clearCompartmentState(tabType);
          }
          return;
        }

        const items = data.items;
        switch (tabType) {
          case 'rapportsPdf':
            setGeneratedReports(prev => {
              const sheetIds = new Set(
                items.flatMap((it: any) =>
                  [it.id, it.reportNumber, it.interventionReference, it.reportId]
                    .filter(Boolean)
                    .map((k: string) => String(k).trim().toLowerCase())
                )
              );
              const hasToursSheet = Boolean(
                getTenantSpreadsheetUrl('spreadsheetTournees', currentCompanyInfo) ||
                  getTenantSpreadsheetUrl('spreadsheetMissionsTournees', currentCompanyInfo)
              );
              const preservedUpcoming = hasToursSheet
                ? (Array.isArray(prev) ? prev : []).filter(
                    (r: any) =>
                      r &&
                      (r.isUpcoming || r.status === 'À venir') &&
                      !sheetIds.has(String(r.id || '').trim().toLowerCase()) &&
                      !sheetIds.has(String(r.interventionReference || '').trim().toLowerCase())
                  )
                : [];
              const combined = [...items, ...preservedUpcoming];
              safeSetLocalStorage(`defib_${activeTid}_generated_reports`, JSON.stringify(combined));
              return combined;
            });
            break;
          case 'crm':
            setTickets(items);
            safeSetLocalStorage(`defib_${activeTid}_support_tickets`, JSON.stringify(items));
            break;
          case 'satisfaction':
            setCustomerReviews(items);
            safeSetLocalStorage(`defib_${activeTid}_customer_reviews`, JSON.stringify(items));
            break;
          case 'commandes':
          case 'devisFactures':
            setCommercialDocs(items);
            safeSetLocalStorage(`defib_${activeTid}_commercial_docs`, JSON.stringify(items));
            break;
          case 'stocksGlobaux':
            setStocks(items);
            safeSetLocalStorage(`defib_${activeTid}_stocks`, JSON.stringify(items));
            break;
          case 'stocksDistribues':
            setDistributedStocks(items);
            safeSetLocalStorage(`defib_${activeTid}_distributed_stocks`, JSON.stringify(items));
            break;
          case 'historiqueNotifications':
            setLogisticsNotifications(items);
            safeSetLocalStorage(`defib_${activeTid}_logistics_notifications`, JSON.stringify(items));
            break;
          case 'achatsFournisseurs':
            setAchatsFournisseurs(items);
            safeSetLocalStorage(`defib_${activeTid}_achats_fournisseurs`, JSON.stringify(items));
            break;
          case 'temps':
            setPointages(items);
            safeSetLocalStorage(`defib_${activeTid}_pointages_history`, JSON.stringify(items));
            break;
          case 'ticketsCaisse':
            setExpenses(items);
            safeSetLocalStorage(`defib_${activeTid}_expenses`, JSON.stringify(items));
            break;
          case 'releveConcurrentiel':
            setVeilles(items);
            safeSetLocalStorage(`defib_${activeTid}_veilles`, JSON.stringify(items));
            break;
          case 'formations':
            setFormations(items);
            safeSetLocalStorage(`defib_${activeTid}_formations`, JSON.stringify(items));
            break;
          case 'stagiaires':
            setStagiaires(items);
            safeSetLocalStorage(`defib_${activeTid}_stagiaires`, JSON.stringify(items));
            break;
          case 'emargements':
            setEmargements(items);
            safeSetLocalStorage(`defib_${activeTid}_emargements`, JSON.stringify(items));
            break;
          case 'messagesInternes': {
            const mappedMsgs: TenantMessage[] = items
              .filter((m: any) => m && (m.content || m.text))
              .map((m: any, idx: number) => ({
                id: m.id || `msg_sheet_${idx + 2}`,
                authorName: m.authorName || m.sender || 'Membre',
                authorEmail: m.authorEmail || '',
                tag: 'All',
                content: m.content || m.text || '',
                createdAt: Number(m.createdAt) || Date.now(),
                dateStr: m.dateStr || m.time || '',
                tenantId: activeTid,
                envId: activeTid,
              }));
            setTenantMessages(mappedMsgs);
            safeSetLocalStorage(`defib_${activeTid}_tenant_messages`, JSON.stringify(mappedMsgs));
            break;
          }
          case 'variables':
            setVariables(items);
            safeSetLocalStorage(`defib_${activeTid}_variables`, JSON.stringify(items));
            break;
          case 'ged':
            setGedDocs(items);
            safeSetLocalStorage(`defib_${activeTid}_ged_docs`, JSON.stringify(items));
            break;
          case 'intituleEmplacements': {
            const nextLocs: Record<string, string> = {};
            const normalizeLocKey = (rawKey: string): string | null => {
              const cleaned = String(rawKey || '').replace(/\.+$/, '').trim();
              const m = cleaned.match(/^(entrep[oô]t|v[eé]hicule)\s*([a-j])$/i);
              if (!m) return null;
              const prefix = m[1].toLowerCase().startsWith('entrep') ? 'Entrepôt' : 'Véhicule';
              return `${prefix} ${m[2].toUpperCase()}`;
            };
            for (const row of items) {
              if (!row || typeof row !== 'object') continue;
              if (row.emplacement && row.intitule !== undefined) {
                const normLoc = normalizeLocKey(String(row.emplacement));
                if (normLoc) {
                  nextLocs[normLoc] = String(row.intitule).trim();
                }
              }
              for (const [k, v] of Object.entries(row)) {
                const normLoc = normalizeLocKey(k);
                if (normLoc && v !== undefined && v !== null) {
                  nextLocs[normLoc] = String(v).trim();
                }
              }
            }
            setLocationNames(nextLocs);
            safeSetLocalStorage(`defib_${activeTid}_custom_location_names`, JSON.stringify(nextLocs));
            break;
          }
          case 'membresEnvironnement': {
            const validSheetMembers = items.filter((m: any) => m && (m.name || m.email));
            // Mix Firebase/DB + Spreadsheet (2 sources), giving spreadsheet fields precedence when an email is in both
            setMembers((prevMembers) => {
              const fbBase = ensureTenantMembersClient(Array.isArray(prevMembers) ? prevMembers : [], activeTid, loggedUser?.email, loggedUser?.name);
              const sheetEmails = new Set(validSheetMembers.map((m: any) => String(m.email || '').trim().toLowerCase()).filter(Boolean));
              const sheetNames = new Set(validSheetMembers.map((m: any) => String(m.name || '').trim().toLowerCase()).filter(Boolean));
              const mergedFromSheet = validSheetMembers.map((sm: any) => {
                const smEmail = String(sm.email || '').trim().toLowerCase();
                const smName = String(sm.name || '').trim().toLowerCase();
                const fbMatch = fbBase.find(
                  (fm: any) =>
                    (smEmail && String(fm.email || '').trim().toLowerCase() === smEmail) ||
                    (!smEmail && smName && String(fm.name || '').trim().toLowerCase() === smName)
                );
                if (fbMatch) {
                  return {
                    ...fbMatch,
                    ...sm,
                    role: sm.role || fbMatch.role,
                  };
                }
                return sm;
              });
              const fbOnly = fbBase.filter((fm: any) => {
                const fmEmail = String(fm.email || '').trim().toLowerCase();
                const fmName = String(fm.name || '').trim().toLowerCase();
                if (fmEmail && sheetEmails.has(fmEmail)) return false;
                if (!fmEmail && fmName && sheetNames.has(fmName)) return false;
                return true;
              });
              const combined = [...fbOnly, ...mergedFromSheet];
              const ensuredCombined = ensureTenantMembersClient(combined, activeTid, loggedUser?.email, loggedUser?.name);
              loadedDataRef.current.members = JSON.stringify(ensuredCombined);
              safeSetLocalStorage(`defib_${activeTid}_members`, JSON.stringify(ensuredCombined));
              return ensuredCombined;
            });
            break;
          }
          case 'reglages':
          case 'apparenceRapportsPdf': {
            const firstRow = items[0];
            if (firstRow && typeof firstRow === 'object') {
              const cleanPatch: Record<string, any> = {};
              for (const [k, v] of Object.entries(firstRow)) {
                if (!k.startsWith('_') && k !== 'id' && v !== undefined) {
                  if (k.startsWith('spreadsheet') && (!v || String(v).trim() === '')) continue;
                  cleanPatch[k] = v;
                }
              }
              if (Object.keys(cleanPatch).length > 0) {
                const langVal = cleanPatch.langue || cleanPatch.language;
                if (langVal) {
                  setLanguage(String(langVal));
                  safeSetLocalStorage(`defib_${activeTid}_lang`, String(langVal));
                }
                if (cleanPatch.enableOtherEquipments) {
                  setEnableOtherEquipments(cleanPatch.enableOtherEquipments);
                  safeSetLocalStorage(`defib_${activeTid}_enable_other_equipments`, cleanPatch.enableOtherEquipments);
                }
                setCompanyInfo((prev) => {
                  let hasDiff = false;
                  for (const [pk, pv] of Object.entries(cleanPatch)) {
                    if ((prev as any)?.[pk] !== pv) {
                      hasDiff = true;
                      break;
                    }
                  }
                  if (!hasDiff) return prev;
                  const next = { ...prev, ...cleanPatch };
                  safeSetLocalStorage(`defib_${activeTid}_company_info`, JSON.stringify(next));
                  return next;
                });
              }
            }
            break;
          }
          case 'communicationPortailClient': {
            const firstRow = items[0];
            const nextMsg = firstRow && typeof firstRow === 'object'
              ? String(firstRow.communicationPortailClient ?? firstRow.message ?? '')
              : '';
            safeSetLocalStorage(`defib_${activeTid}_communication_portail_client`, nextMsg);
            setCompanyInfo((prev) => {
              if (prev.communicationPortailClient === nextMsg) return prev;
              return {
                ...prev,
                communicationPortailClient: nextMsg,
              };
            });
            break;
          }
          case 'reglagesCrm': {
            const firstRow = items[0];
            if (firstRow && typeof firstRow === 'object') {
              const crmSettingsObj = {
                relanceEmailBody: firstRow.relanceEmailBody ?? '',
                relanceEmailReplyTo: firstRow.relanceEmailReplyTo ?? '',
                relanceEmailBody2: firstRow.relanceEmailBody2 ?? '',
                relanceEmailReplyTo2: firstRow.relanceEmailReplyTo2 ?? '',
                relanceEmailBody3: firstRow.relanceEmailBody3 ?? '',
                relanceEmailReplyTo3: firstRow.relanceEmailReplyTo3 ?? '',
                supportEmailBody: firstRow.supportEmailBody ?? '',
                supportEmailReplyTo: firstRow.supportEmailReplyTo ?? '',
                supportEmailSubject: firstRow.supportEmailSubject ?? '',
              };
              if (firstRow.relanceEmailBody !== undefined) {
                safeSetLocalStorage(`defib_${activeTid}_crm_relance_template`, String(firstRow.relanceEmailBody || ''));
              }
              if (firstRow.relanceEmailReplyTo !== undefined) {
                safeSetLocalStorage(`defib_${activeTid}_crm_relance_replyto`, String(firstRow.relanceEmailReplyTo || ''));
              }
              if (firstRow.relanceEmailBody2 !== undefined) {
                safeSetLocalStorage(`defib_${activeTid}_crm_relance_template_2`, String(firstRow.relanceEmailBody2 || ''));
              }
              if (firstRow.relanceEmailReplyTo2 !== undefined) {
                safeSetLocalStorage(`defib_${activeTid}_crm_relance_replyto_2`, String(firstRow.relanceEmailReplyTo2 || ''));
              }
              if (firstRow.relanceEmailBody3 !== undefined) {
                safeSetLocalStorage(`defib_${activeTid}_crm_relance_template_3`, String(firstRow.relanceEmailBody3 || ''));
              }
              if (firstRow.relanceEmailReplyTo3 !== undefined) {
                safeSetLocalStorage(`defib_${activeTid}_crm_relance_replyto_3`, String(firstRow.relanceEmailReplyTo3 || ''));
              }
              if (firstRow.supportEmailBody !== undefined) {
                safeSetLocalStorage(`defib_${activeTid}_crm_support_template`, String(firstRow.supportEmailBody || ''));
              }
              if (firstRow.supportEmailReplyTo !== undefined) {
                safeSetLocalStorage(`defib_${activeTid}_crm_support_replyto`, String(firstRow.supportEmailReplyTo || ''));
              }
              if (firstRow.supportEmailSubject !== undefined) {
                safeSetLocalStorage(`defib_${activeTid}_crm_support_subject`, String(firstRow.supportEmailSubject || ''));
              }
              safeSetLocalStorage(`defib_${activeTid}_crm_settings`, JSON.stringify(crmSettingsObj));
              if (typeof window !== 'undefined') {
                window.dispatchEvent(
                  new CustomEvent('defib-crm-settings-updated', {
                    detail: { tenantId: activeTid, settings: firstRow },
                  })
                );
              }
            }
            break;
          }
          case 'observateurActionsSuspectes': {
            setSuspiciousActivityLogs(items);
            safeSetLocalStorage(`defib_${activeTid}_suspicious_activity_logs`, JSON.stringify(items));
            break;
          }
          default:
            break;
        }
      } catch (err) {
        console.warn(`Error refreshing generic sheet compartment (${tabType}):`, err);
      }
    },
    [tenantId, loggedUser?.email, loggedUser?.name, ensureFsmTourIdentifiers]
  );

  // Listen to manual refresh events from TableSubHeaderButtons or SettingsModal
  useEffect(() => {
    const keyToTabMap: Record<string, string> = {
      spreadsheetTournees: 'tournees',
      spreadsheetMissionsTournees: 'missionsTournees',
      spreadsheetRapportsPdf: 'rapportsPdf',
      spreadsheetCrm: 'crm',
      spreadsheetReglagesCrm: 'reglagesCrm',
      spreadsheetSatisfaction: 'satisfaction',
      spreadsheetCommandes: 'commandes',
      spreadsheetDevisFactures: 'devisFactures',
      spreadsheetStocks: 'stocksGlobaux',
      spreadsheetStocksGlobaux: 'stocksGlobaux',
      spreadsheetStocksDistribues: 'stocksDistribues',
      spreadsheetHistoriqueNotifications: 'historiqueNotifications',
      spreadsheetAchatsFournisseurs: 'achatsFournisseurs',
      spreadsheetTemps: 'temps',
      spreadsheetTicketsCaisse: 'ticketsCaisse',
      spreadsheetReleveConcurrentiel: 'releveConcurrentiel',
      spreadsheetFormations: 'formations',
      spreadsheetStagiaires: 'stagiaires',
      spreadsheetEmargements: 'emargements',
      spreadsheetMessagesInternes: 'messagesInternes',
      spreadsheetVariables: 'variables',
      spreadsheetGed: 'ged',
      spreadsheetIntituleEmplacements: 'intituleEmplacements',
      spreadsheetMembresEnvironnement: 'membresEnvironnement',
      spreadsheetReglages: 'reglages',
      spreadsheetApparenceRapportsPdf: 'apparenceRapportsPdf',
      spreadsheetCommunicationPortailClient: 'communicationPortailClient',
      spreadsheetObservateurActionsSuspectes: 'observateurActionsSuspectes',
    };

    const handleManualSheetRefresh = (e: Event) => {
      const detail = (e as CustomEvent)?.detail;
      const spreadsheetKey = detail?.spreadsheetKey;
      const tabType = spreadsheetKey ? keyToTabMap[spreadsheetKey] : detail?.tabType;
      if (tabType) {
        refreshGenericSheetCompartment(tabType, true);
      }
    };

    window.addEventListener('defib-manual-refresh-spreadsheet', handleManualSheetRefresh);
    return () => {
      window.removeEventListener('defib-manual-refresh-spreadsheet', handleManualSheetRefresh);
    };
  }, [refreshGenericSheetCompartment]);

  // Also load any configured secondary Google Spreadsheets for the active tenant on startup and whenever spreadsheet URLs change
  useEffect(() => {
    if (
      !isLoggedIn ||
      !tenantId ||
      tenantId.toLowerCase() === 'megaadmin' ||
      localStorage.getItem('defib_logged_user_role') === 'megaadmin' ||
      !isFirebaseLoaded ||
      loadedTenantIdState !== tenantId
    )
      return;
    const secondaryTabTypes = [
      'tournees',
      'rapportsPdf',
      'crm',
      'reglagesCrm',
      'satisfaction',
      'commandes',
      'stocksGlobaux',
      'stocksDistribues',
      'historiqueNotifications',
      'achatsFournisseurs',
      'temps',
      'ticketsCaisse',
      'releveConcurrentiel',
      'formations',
      'stagiaires',
      'emargements',
      'messagesInternes',
      'variables',
      'ged',
      'intituleEmplacements',
      'membresEnvironnement',
      'reglages',
      'apparenceRapportsPdf',
      'communicationPortailClient',
      'observateurActionsSuspectes',
    ];
    const runAll = (force = false) => {
      secondaryTabTypes.forEach((tt) => {
        refreshGenericSheetCompartment(tt, force);
      });
    };
    const timer = setTimeout(() => {
      runAll(false);
    }, 150);
    const handleSheetsUpdated = () => {
      runAll(true);
    };
    window.addEventListener('defib-tenant-spreadsheets-updated', handleSheetsUpdated);
    return () => {
      clearTimeout(timer);
      window.removeEventListener('defib-tenant-spreadsheets-updated', handleSheetsUpdated);
    };
  }, [isLoggedIn, tenantId, isFirebaseLoaded, loadedTenantIdState, refreshGenericSheetCompartment]);

  const [isRefreshingCrm, setIsRefreshingCrm] = useState<boolean>(false);
  const handleManualRefreshCrm = async () => {
    if (!tenantId) return;
    setIsRefreshingCrm(true);
    try {
      // 1. Refresh CRM, CRM Settings, and Membres from Google Spreadsheets if configured
      await Promise.all([
        refreshGenericSheetCompartment('crm', true),
        refreshGenericSheetCompartment('reglagesCrm', true),
        refreshGenericSheetCompartment('membresEnvironnement', true),
      ]);

      // 2. Refresh clients from Google Spreadsheet
      await handleManualRefreshClients();
    } catch (err) {
      console.warn('Manual refresh error in CRM:', err);
    } finally {
      setTimeout(() => {
        setIsRefreshingCrm(false);
      }, 500);
    }
  };

  const [isRefreshingFsm, setIsRefreshingFsm] = useState<boolean>(false);
  const handleManualRefreshFsm = async () => {
    if (isRefreshingFsm) return;
    setIsRefreshingFsm(true);
    try {
      await Promise.all([
        refreshGenericSheetCompartment('tournees', true),
        refreshGenericSheetCompartment('stocksGlobaux', true),
        refreshGenericSheetCompartment('stocksDistribues', true),
        refreshGenericSheetCompartment('variables', true),
        refreshGenericSheetCompartment('membresEnvironnement', true),
        refreshGenericSheetCompartment('commandes', true),
      ]);
    } catch (err) {
      console.warn('Manual refresh error in Tournées & Missions:', err);
    } finally {
      setTimeout(() => {
        setIsRefreshingFsm(false);
      }, 500);
    }
  };

  const [isRefreshingRapportsPdf, setIsRefreshingRapportsPdf] = useState<boolean>(false);
  const handleManualRefreshRapportsPdf = async () => {
    if (isRefreshingRapportsPdf) return;
    setIsRefreshingRapportsPdf(true);
    try {
      await Promise.all([
        refreshGenericSheetCompartment('rapportsPdf', true),
        refreshGenericSheetCompartment('tournees', true),
      ]);
    } catch (err) {
      console.warn('Manual refresh error in Rapports PDF:', err);
    } finally {
      setTimeout(() => {
        setIsRefreshingRapportsPdf(false);
      }, 500);
    }
  };

  const saveReviews = (updated: any[]) => {
    syncCompartmentToGoogleSheets('satisfaction', customerReviews, updated, ['id', 'missionRef']);
    setCustomerReviews(updated);
    localStorage.setItem(`defib_${tenantId}_customer_reviews`, JSON.stringify(updated));
    if (isFirebaseLoaded && tenantId) {
      saveCollectionToFirestore('customerReviews', updated, tenantId).catch(() => {});
    }
  };

  const [editingPointageId, setEditingPointageId] = useState<string | null>(null);
  const [editPointageForm, setEditPointageForm] = useState<{
    startDate: string;
    startTime: string;
    endDate: string;
    endTime: string;
  } | null>(null);

  const [expenses, setExpenses] = useState<any[]>([]);
  const [veilles, setVeilles] = useState<VeilleRecord[]>([]);

  // Sync and manage technician generated reports in main GMAO tab
  const [generatedReports, setGeneratedReports] = useState<any[]>([]);
  const [editingReportId, setEditingReportId] = useState<string | null>(null);
  const [editReportForm, setEditReportForm] = useState<{
    title: string;
    techName: string;
    defibIdentifiant: string;
    siteMission: string;
  } | null>(null);

  // Mute audio effects when side pane Corriger is open in the main software
  useEffect(() => {
    if (editingReportId) {
      setAudioMutedInMainSoftware(true);
      return () => {
        setAudioMutedInMainSoftware(false);
      };
    }
  }, [editingReportId]);

  const toggleGmaoTableFitView = () => {
    setGmaoIsTableFitView(prev => {
      const next = !prev;
      if (next) {
        if (gmaoTableContainerRef.current) {
          const sWidth = gmaoTableContainerRef.current.scrollWidth;
          if (sWidth > 500) {
            gmaoNaturalTableWidthRef.current = sWidth;
          }
          const clientW = gmaoTableContainerRef.current.clientWidth;
          const naturalW = gmaoNaturalTableWidthRef.current || 1500;
          const scale = Math.min(1, Math.max(0.1, (clientW - 2) / naturalW));
          setGmaoTableFitScale(scale);
        }
      } else {
        setGmaoTableFitScale(1);
      }
      return next;
    });
  };

  useEffect(() => {
    if (activeTab !== 'gmao' || !gmaoTableContainerRef.current) return;

    const updateWidth = () => {
      if (!gmaoTableContainerRef.current) return;
      const clientW = gmaoTableContainerRef.current.clientWidth;
      if (!gmaoIsTableFitView) {
        const sWidth = gmaoTableContainerRef.current.scrollWidth;
        if (sWidth > 500) {
          gmaoNaturalTableWidthRef.current = sWidth;
        }
        setGmaoTableFitScale(1);
      } else {
        const naturalW = gmaoNaturalTableWidthRef.current || 1500;
        const scale = Math.min(1, Math.max(0.1, (clientW - 2) / naturalW));
        setGmaoTableFitScale(scale);
      }
    };

    updateWidth();
    const timer = setTimeout(updateWidth, 150);

    const observer = new ResizeObserver(updateWidth);
    observer.observe(gmaoTableContainerRef.current);

    window.addEventListener('resize', updateWidth);

    return () => {
      clearTimeout(timer);
      observer.disconnect();
      window.removeEventListener('resize', updateWidth);
    };
  }, [activeTab, gmaoIsTableFitView, gmaoFilter, gmaoSearchQuery, gmaoIncludeAutresMateriels, generatedReports]);

  const saveReports = (updated: any[]) => {
    const oldReal = (Array.isArray(generatedReports) ? generatedReports : []).filter(
      (r: any) => r && !r.isUpcoming && r.status !== 'À venir'
    );
    const newReal = (Array.isArray(updated) ? updated : []).filter(
      (r: any) => r && !r.isUpcoming && r.status !== 'À venir'
    );
    syncCompartmentToGoogleSheets(
      'rapportsPdf',
      oldReal,
      newReal,
      ['interventionReference', 'reportNumber', 'id', 'reportId']
    );
    setGeneratedReports(updated);
    try {
      localStorage.setItem(`defib_${tenantId}_generated_reports`, JSON.stringify(updated));
    } catch (e) {
      console.warn("Storage quota exceeded in saveReports:", e);
    }
    if (isFirebaseLoaded && tenantId === loadedTenantIdRef.current) {
      saveCollectionToFirestore('generatedReports', updated, tenantId);
    }
  };

  const [fsmTours, setFsmTours] = useState<any[]>([]);

  const saveFsmTours = (updated: any[]) => {
    if (isDeveloper) {
      alert("Action non autorisée : Le rôle Développeur est en mode lecture seule.");
      return;
    }
    const { tours: rawWithIds } = ensureFsmTourIdentifiers(updated, tenantId);
    const withIds = (rawWithIds || []).map((tour: any) => {
      if (!tour || !Array.isArray(tour.missions)) return tour;
      return {
        ...tour,
        missions: tour.missions.map((m: any, mIdx: number) => {
          if (!m || String(m.id || '').startsWith('log-')) return m;
          const rawRef = String(m.interventionReference || '').trim();
          const cleanRef =
            rawRef && !rawRef.startsWith('fsm-m-')
              ? rawRef
              : `INT-2026-${String(rawRef || m.id || Date.now() + mIdx).replace(/\D/g, '').slice(-5).padStart(5, '0')}`;
          const eqIdent = String(
            m.defibIdentifiant || (!String(m.identifiant || '').startsWith('fsm-m-') ? m.identifiant : '') || ''
          ).trim();
          return {
            ...m,
            status: m.status || 'Brouillon',
            interventionReference: cleanRef,
            defibIdentifiant: eqIdent || m.defibIdentifiant || '',
            identifiant: eqIdent || m.defibIdentifiant || '',
          };
        }),
      };
    });

    // Synchronize Tournées (excluding 'a-trier') and Missions des tournées (all real missions) to Google Spreadsheets
    try {
      const oldRealTours = (fsmTours || []).filter((t: any) => t && t.id !== 'a-trier');
      const newRealTours = (withIds || []).filter((t: any) => t && t.id !== 'a-trier');
      syncCompartmentToGoogleSheets('tournees', oldRealTours, newRealTours, ['tourIdentifiant', 'id', 'tourCode']);

      const extractFlatMissions = (toursList: any[]) => {
        const list: any[] = [];
        for (const t of toursList || []) {
          if (!t || !Array.isArray(t.missions)) continue;
          const tourIdent = t.id === 'a-trier' ? '' : (t.tourIdentifiant || t.id || '');
          for (const m of t.missions) {
            if (!m || String(m.id || '').startsWith('log-')) continue;
            const eqIdent = String(
              m.defibIdentifiant || (!String(m.identifiant || '').startsWith('fsm-m-') ? m.identifiant : '') || ''
            ).trim();
            const matchedDefib = eqIdent ? defibrillateurs.find((d: any) => d.identifiant === eqIdent) : null;
            const other = !matchedDefib && eqIdent ? otherEquipments.find((o: any) => o.identifiant === eqIdent) : null;
            const clientObj = clients?.find(
              (c: any) => c.id === (m.clientId || matchedDefib?.clientId || other?.clientId)
            );
            const resolvedClientName = clientObj ? clientObj.denomination : (m.clientName || '');
            const resolvedSiteName =
              m.siteName ||
              (matchedDefib ? matchedDefib.nomSite || '' : other ? other.nomPrenomSite || '' : '');
            const ville = m.ville || (matchedDefib ? matchedDefib.ville : other ? other.ville : '') || '';
            const cp =
              m.cp ||
              (matchedDefib ? matchedDefib.codePostal || matchedDefib.cp || '' : other ? other.codePostal || other.cp || '' : '') ||
              '';
            const resolvedAddress =
              m.clientAddress || m.location || (ville && cp ? `${ville}, ${cp}` : ville || cp || '');
            const rawRef = String(m.interventionReference || '').trim();
            const cleanRef =
              rawRef && !rawRef.startsWith('fsm-m-')
                ? rawRef
                : `INT-2026-${String(rawRef || m.id || Date.now()).replace(/\D/g, '').slice(-5).padStart(5, '0')}`;
            list.push({
              ...m,
              tourIdentifiant: tourIdent,
              tourId: t.id === 'a-trier' ? '' : t.id,
              defibIdentifiant: eqIdent,
              identifiant: eqIdent,
              interventionReference: cleanRef,
              clientName: resolvedClientName,
              siteName: resolvedSiteName,
              ville,
              cp,
              clientAddress: resolvedAddress,
              techName: m.techName || (t.id !== 'a-trier' ? t.techName : ''),
            });
          }
        }
        return list;
      };

      const oldFlatMissions = extractFlatMissions(fsmTours || []);
      const newFlatMissions = extractFlatMissions(withIds || []);
      syncCompartmentToGoogleSheets('missionsTournees', oldFlatMissions, newFlatMissions, [
        'interventionReference',
        'id',
        'defibIdentifiant',
      ]);
    } catch (sheetErr) {
      console.warn('Error syncing tours/missions to Google Sheets:', sheetErr);
    }

    setFsmTours(withIds);
    try {
      localStorage.setItem(`defib_${tenantId}_fsm_tours`, JSON.stringify(withIds));
    } catch (e) {
      console.warn("Storage quota exceeded in saveFsmTours:", e);
    }
    if (isFirebaseLoaded && tenantId === loadedTenantIdRef.current) {
      saveCollectionToFirestore('fsmTours', withIds, tenantId);
    }
  };

  // Synchronize tour missions with pending report lines in GMAO "Rapports PDF"
  useEffect(() => {
    const rapportsSheetUrl = getTenantSpreadsheetUrl('spreadsheetRapportsPdf', companyInfo);
    const hasToursSheet = Boolean(
      getTenantSpreadsheetUrl('spreadsheetTournees', companyInfo) ||
        getTenantSpreadsheetUrl('spreadsheetMissionsTournees', companyInfo)
    );
    if (!rapportsSheetUrl && !hasToursSheet) {
      return;
    }
    if (!Array.isArray(fsmTours) || fsmTours.length === 0) {
      return;
    }

    // 1. Ensure all tours have a frozen tourIdentifiant and all missions have a unique interventionReference
    const { tours: toursWithIds, changed: idsChanged } = ensureFsmTourIdentifiers(fsmTours, tenantId);
    let toursUpdated = idsChanged;
    const verifiedTours = toursWithIds.map((tour) => {
      let tourMissionsUpdated = false;
      const verifiedMissions = (Array.isArray(tour?.missions) ? tour.missions : []).map((m: any) => {
        const rawRef = String(m.interventionReference || '').trim();
        if (!rawRef || rawRef.startsWith('fsm-m-')) {
          tourMissionsUpdated = true;
          const digits = String(rawRef || m.id || Date.now()).replace(/\D/g, '');
          const ref = `INT-2026-${digits.slice(-5).padStart(5, '0')}`;
          return { ...m, status: m.status || 'Brouillon', interventionReference: ref };
        }
        return { ...m, status: m.status || 'Brouillon' };
      });

      if (tourMissionsUpdated) {
        toursUpdated = true;
        return { ...tour, missions: verifiedMissions };
      }
      return tour;
    });

    if (toursUpdated) {
      setFsmTours(verifiedTours);
      safeSetLocalStorage(`defib_${tenantId}_fsm_tours`, JSON.stringify(verifiedTours));
      return;
    }

    // 2. Map active missions across all tours
    const activeMissionsMap = new Map<string, { mission: any; tour: any }>();
    verifiedTours.forEach((tour) => {
      (Array.isArray(tour?.missions) ? tour.missions : []).forEach((m: any) => {
        if (m.id) {
          activeMissionsMap.set(m.id, { mission: m, tour });
        }
        if (m.interventionReference) {
          activeMissionsMap.set(m.interventionReference, { mission: m, tour });
        }
      });
    });

    const isFormationMission = (m: any) => {
      if (!m) return false;
      return (
        m.equipmentType === 'Formation' ||
        m.equipmentType?.toLowerCase()?.includes('formation') ||
        !!m.formationId ||
        m.reason?.toLowerCase()?.includes('formation') ||
        m.defibIdentifiant === 'Formation'
      );
    };

    // 3. Synchronize generatedReports array
    let reportsChanged = false;
    const safeGeneratedReports = Array.isArray(generatedReports) ? generatedReports : [];
    
    // Filter out Formation mission reports and orphaned pending upcoming reports
    let updatedReports = safeGeneratedReports.filter((rep) => {
      const matchedMissionObj = 
        (rep.missionId && activeMissionsMap.get(rep.missionId)?.mission) ||
        (rep.interventionReference && activeMissionsMap.get(rep.interventionReference)?.mission);

      const isFormation = 
        rep.equipmentType === 'Formation' ||
        rep.equipmentType?.toLowerCase()?.includes('formation') ||
        rep.defibSnapshot?.categorie === 'Formation' ||
        rep.defibSnapshot?.categorie?.toLowerCase()?.includes('formation') ||
        !!rep.formationId ||
        rep.defibIdentifiant === 'Formation' ||
        (matchedMissionObj && isFormationMission(matchedMissionObj));

      if (isFormation) {
        reportsChanged = true;
        return false; // Do NOT create or keep record/report in RAPPORT PDF for Formation missions
      }

      const isUpcoming = rep.isUpcoming || rep.status === 'À venir';
      if (isUpcoming) {
        const existsInTours = 
          (rep.missionId && activeMissionsMap.has(rep.missionId)) || 
          (rep.interventionReference && activeMissionsMap.has(rep.interventionReference));
        if (!existsInTours) {
          reportsChanged = true;
          return false; // Remove pending report since mission was deleted
        }
      }
      return true;
    });

    // Ensure each active NON-FORMATION mission has an associated report (either real or pending)
    verifiedTours.forEach((tour) => {
      (tour.missions || []).forEach((m: any) => {
        if (isFormationMission(m)) return; // DO NOT create report line for Formation missions

        const existingReportIndex = updatedReports.findIndex(r => 
          (m.id && r.missionId === m.id) || 
          (m.interventionReference && r.interventionReference === m.interventionReference)
        );

        const tourOrigin = `${tour.startDate || tour.date || ''} ${tour.title || tour.name || ''}`.trim();

        if (existingReportIndex === -1) {
          // Pre-create pending report line in Rapports PDF
          reportsChanged = true;
          const upcomingRep = {
            id: `REP-UPCOMING-${m.id || Date.now()}`,
            missionId: m.id,
            defibIdentifiant: m.defibIdentifiant,
            interventionReference: m.interventionReference,
            autreReference: m.autreReference || '',
            isUpcoming: true,
            status: 'À venir',
            validated: false,
            techName: tour.techName || 'Non assigné',
            date: tour.startDate || tour.date || 'À venir',
            estimatedDate: m.estimatedDate || tour.startDate || tour.date || '',
            estimatedSlot: m.estimatedSlot || '',
            tourName: tour.title || tour.name || `Tournée ${tour.id}`,
            tourDate: tour.startDate || tour.date || '',
            origin: tourOrigin,
            missionStatus: m.status || 'Brouillon',
            defibSnapshot: { 
              identifiant: m.defibIdentifiant, 
              categorie: m.equipmentType || 'Défibrillateur' 
            },
            siteMission: m.clientName || 'Site'
          };
          updatedReports.push(upcomingRep);
        } else {
          const existing = updatedReports[existingReportIndex];
          if (existing.isUpcoming) {
            // Keep pending report details synchronized with tour mission changes
            if (
              existing.missionStatus !== (m.status || 'Brouillon') ||
              existing.techName !== (tour.techName || 'Non assigné') ||
              existing.origin !== tourOrigin ||
              existing.defibIdentifiant !== m.defibIdentifiant ||
              existing.autreReference !== (m.autreReference || '') ||
              existing.estimatedDate !== (m.estimatedDate || tour.startDate || tour.date || '') ||
              existing.estimatedSlot !== (m.estimatedSlot || '')
            ) {
              reportsChanged = true;
              updatedReports[existingReportIndex] = {
                ...existing,
                missionStatus: m.status || 'Brouillon',
                techName: tour.techName || 'Non assigné',
                tourName: tour.title || tour.name || `Tournée ${tour.id}`,
                tourDate: tour.startDate || tour.date || '',
                estimatedDate: m.estimatedDate || tour.startDate || tour.date || '',
                estimatedSlot: m.estimatedSlot || '',
                origin: tourOrigin,
                defibIdentifiant: m.defibIdentifiant,
                autreReference: m.autreReference || '',
                defibSnapshot: { ...existing.defibSnapshot, identifiant: m.defibIdentifiant }
              };
            }
          }
        }
      });
    });

    if (reportsChanged) {
      setGeneratedReports(updatedReports);
      safeSetLocalStorage(`defib_${tenantId}_generated_reports`, JSON.stringify(updatedReports));
    }
  }, [fsmTours, generatedReports, companyInfo, tenantId, ensureFsmTourIdentifiers]);

  // Helper to parse dates and timestamps in various standard and French formats
  const parseTimestampHelper = (str: any): Date | null => {
    if (!str || typeof str !== 'string') return null;
    const s = str.trim();
    if (!s) return null;

    const matchFR = s.match(/^(\d{1,2})[/-](\d{1,2})[/-](\d{4})(?:[ ,Tà@]+(\d{1,2}):(\d{1,2})(?::(\d{1,2}))?)?/i);
    if (matchFR) {
      const day = parseInt(matchFR[1], 10);
      const month = parseInt(matchFR[2], 10) - 1;
      const year = parseInt(matchFR[3], 10);
      const hours = matchFR[4] ? parseInt(matchFR[4], 10) : 0;
      const minutes = matchFR[5] ? parseInt(matchFR[5], 10) : 0;
      const seconds = matchFR[6] ? parseInt(matchFR[6], 10) : 0;
      const d = new Date(year, month, day, hours, minutes, seconds);
      if (!isNaN(d.getTime())) return d;
    }

    const matchISO = s.match(/^(\d{4})[/-](\d{1,2})[/-](\d{1,2})(?:[ ,Tà@]+(\d{1,2}):(\d{1,2})(?::(\d{1,2}))?)?/i);
    if (matchISO) {
      const year = parseInt(matchISO[1], 10);
      const month = parseInt(matchISO[2], 10) - 1;
      const day = parseInt(matchISO[3], 10);
      const hours = matchISO[4] ? parseInt(matchISO[4], 10) : 0;
      const minutes = matchISO[5] ? parseInt(matchISO[5], 10) : 0;
      const seconds = matchISO[6] ? parseInt(matchISO[6], 10) : 0;
      const d = new Date(year, month, day, hours, minutes, seconds);
      if (!isNaN(d.getTime())) return d;
    }

    const standard = new Date(s);
    if (!isNaN(standard.getTime())) return standard;

    return null;
  };

  // Clé du mois en cours par défaut (ex: "2026-09" ou "2026-02")
  const currentMonthKey = useMemo(() => {
    const now = new Date();
    const y = now.getFullYear();
    const m = String(now.getMonth() + 1).padStart(2, '0');
    return `${y}-${m}`;
  }, []);

  // Mois sélectionné pour les statistiques FSM (Temps moyen & CO2 préservé)
  const [selectedFsmMonth, setSelectedFsmMonth] = useState<string>(() => {
    const now = new Date();
    const y = now.getFullYear();
    const m = String(now.getMonth() + 1).padStart(2, '0');
    return `${y}-${m}`;
  });
  const [fsmClickedPill, setFsmClickedPill] = useState<{ id: string; key: number } | null>(null);
  const triggerFsmPillWave = (id: string) => {
    setFsmClickedPill(null);
    requestAnimationFrame(() => {
      setFsmClickedPill({ id, key: Date.now() });
    });
  };

  // Helper pour extraire le mois YYYY-MM d'un rapport
  const getReportMonthKey = (rep: any): string => {
    if (!rep) return '';
    const dStr = rep.date || rep.interventionDate || rep.horodatage || rep.startTimeStamp || rep.dateIntervention || rep.horodatageEntrant || rep.tourDate || rep.dateRapport || rep.scheduledDate || rep.createdAt;
    if (!dStr) return '';
    if (typeof dStr === 'string' && /^\d{4}-\d{2}/.test(dStr.trim())) {
      return dStr.trim().slice(0, 7);
    }
    const d = parseTimestampHelper(dStr);
    if (d && !isNaN(d.getTime())) {
      return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;
    }
    return '';
  };

  // Extraction robuste de la clé mois YYYY-MM pour une tournée ou ses missions
  const getTourMonthKey = (tour: any): string => {
    if (!tour) return '';
    const rawDates: any[] = [
      tour.startDate,
      tour.date,
      ...(Array.isArray(tour.missions) ? tour.missions.map((m: any) => m?.estimatedDate || m?.date || m?.scheduledDate) : [])
    ].filter(Boolean);

    for (const raw of rawDates) {
      if (typeof raw !== 'string') continue;
      const s = raw.trim();
      if (!s || s === 'A trier' || s === 'a-trier' || s === '--' || s === 'NC') continue;

      // Format ISO YYYY-MM...
      if (/^\d{4}-\d{2}/.test(s)) {
        return s.slice(0, 7);
      }
      // Format FR DD/MM/YYYY ou DD-MM-YYYY
      const frMatch = s.match(/^(\d{1,2})[/-](\d{1,2})[/-](\d{4})/);
      if (frMatch) {
        const month = String(parseInt(frMatch[2], 10)).padStart(2, '0');
        const year = frMatch[3];
        return `${year}-${month}`;
      }
      // Helper Date
      const d = parseTimestampHelper(s);
      if (d && !isNaN(d.getTime())) {
        return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;
      }
    }
    return '';
  };

  // Temps moyen d'une intervention en minutes (dynamique, recalculé selon le mois FSM sélectionné)
  const avgInterventionMinutesStr = useMemo(() => {
    if (!selectedFsmMonth) return "N/A";

    let totalDurationMinutes = 0;
    let countedInterventions = 0;
    const handledReportIds = new Set<string>();

    const safeFsmTours = Array.isArray(fsmTours) ? fsmTours : [];
    const safeGeneratedReports = Array.isArray(generatedReports) ? generatedReports : [];
    const safeVariables = Array.isArray(variables) ? variables : [];
    const safePointages = Array.isArray(pointages) ? pointages : [];

    // 1. Interventions des missions dans les tournées FSM du mois sélectionné
    const activeToursInMonth = safeFsmTours.filter(t => {
      if (!t || t.id === 'a-trier') return false;
      const mKey = getTourMonthKey(t);
      return mKey === selectedFsmMonth;
    });

    activeToursInMonth.forEach(t => {
      if (!Array.isArray(t.missions)) return;
      t.missions.forEach((m: any) => {
        let missionMinutes = 0;

        // A. Vérifier si un rapport GMAO a été généré pour cette mission avec des horaires réels
        const matchedReport = safeGeneratedReports.find((rep: any) => {
          if (!rep) return false;
          if (rep.id && (rep.id === m.reportId || rep.id === m.id)) return true;
          if (rep.missionId && rep.missionId === m.id) return true;
          if (rep.tourId === t.id && rep.defibIdentifiant && m.defibIdentifiant && rep.defibIdentifiant === m.defibIdentifiant) return true;
          return false;
        });

        if (matchedReport) {
          handledReportIds.add(matchedReport.id);
          const startStr = matchedReport.date || matchedReport.interventionDate || matchedReport.horodatage || matchedReport.startTimeStamp || matchedReport.dateIntervention || matchedReport.horodatageEntrant;
          const endStr = matchedReport.endTimeStamp || matchedReport.horodatageCloture || matchedReport.heureFin || matchedReport.horodatageSortant || matchedReport.dateCloture;
          const start = parseTimestampHelper(startStr);
          const end = parseTimestampHelper(endStr);
          if (start && end) {
            const diffMin = Math.round((end.getTime() - start.getTime()) / 60000);
            if (diffMin > 0) missionMinutes = diffMin;
          } else if (typeof matchedReport.durationSeconds === 'number' && matchedReport.durationSeconds > 0) {
            missionMinutes = Math.round(matchedReport.durationSeconds / 60);
          } else if (matchedReport.dureePrestation && Number(matchedReport.dureePrestation) > 0) {
            missionMinutes = Number(matchedReport.dureePrestation);
          }
        }

        // B. Si pas de durée effective via rapport, utiliser la durée configurée sur la mission FSM
        if (missionMinutes <= 0) {
          if (m.dureePrestation !== undefined && !isNaN(Number(m.dureePrestation)) && Number(m.dureePrestation) > 0) {
            missionMinutes = Number(m.dureePrestation);
          } else {
            // Chercher dans les variables pour la durée des prestations
            const reasonsList: string[] = Array.isArray(m.reasons) && m.reasons.length > 0
              ? m.reasons
              : (m.reason ? String(m.reason).split(',').map((s: string) => s.trim()).filter(Boolean) : []);
            
            let reasonsSum = 0;
            for (const r of reasonsList) {
              const matchVar = safeVariables.find((v: any) =>
                v &&
                v.category === 'Modèle Raison Prestation' &&
                (v.nom?.toLowerCase().trim() === r.toLowerCase().trim() || v.id === r)
              );
              if (matchVar?.dureePrestation && !isNaN(Number(matchVar.dureePrestation))) {
                reasonsSum += Number(matchVar.dureePrestation);
              }
            }

            if (reasonsSum > 0) {
              missionMinutes = reasonsSum;
            } else if (m.duration && !isNaN(Number(m.duration)) && Number(m.duration) > 0) {
              missionMinutes = Number(m.duration);
            } else {
              // Durée standard d'une intervention de maintenance si non précisée
              missionMinutes = 45;
            }
          }
        }

        if (missionMinutes > 0) {
          totalDurationMinutes += missionMinutes;
          countedInterventions++;
        }
      });
    });

    // 2. Rapports GMAO indépendants du mois sélectionné (non déjà pris en compte avec les tournées)
    safeGeneratedReports.forEach((rep: any) => {
      if (!rep || handledReportIds.has(rep.id)) return;

      const isFormation =
        rep.equipmentType === 'Formation' ||
        rep.equipmentType?.toLowerCase()?.includes('formation') ||
        rep.defibSnapshot?.categorie === 'Formation' ||
        rep.defibSnapshot?.categorie?.toLowerCase()?.includes('formation') ||
        !!rep.formationId ||
        rep.defibIdentifiant === 'Formation';
      if (isFormation) return;

      const isEffectue =
        rep.missionStatus === 'Effectué' ||
        rep.conforme === 'Conforme' ||
        rep.conforme === 'Non Conforme' ||
        rep.conforme === 'Intervention impossible' ||
        !!rep.validated;

      const isUpcoming = !isEffectue && (rep.isUpcoming || rep.status === 'À venir' || rep.status === 'upcoming' || rep.upcoming || rep.isFuture);
      if (isUpcoming) return;

      // Filtrage strict par le mois sélectionné
      const mKey = getReportMonthKey(rep);
      if (!mKey || mKey !== selectedFsmMonth) return;

      const startStr = rep.date || rep.interventionDate || rep.horodatage || rep.startTimeStamp || rep.dateIntervention || rep.horodatageEntrant;
      const endStr = rep.endTimeStamp || rep.horodatageCloture || rep.heureFin || rep.horodatageSortant || rep.dateCloture;
      const start = parseTimestampHelper(startStr);
      const end = parseTimestampHelper(endStr);

      let repMinutes = 0;
      if (start && end) {
        const diffMs = end.getTime() - start.getTime();
        if (diffMs > 0) repMinutes = Math.round(diffMs / 60000);
      } else if (typeof rep.durationSeconds === 'number' && rep.durationSeconds > 0) {
        repMinutes = Math.round(rep.durationSeconds / 60);
      } else if (rep.dureePrestation && Number(rep.dureePrestation) > 0) {
        repMinutes = Number(rep.dureePrestation);
      }

      if (repMinutes > 0) {
        totalDurationMinutes += repMinutes;
        countedInterventions++;
      }
    });

    // 3. Fallback aux pointages du mois sélectionné si aucune tournée ou rapport avec durée
    if (countedInterventions === 0) {
      const finished = safePointages.filter(p => {
        if (!p || p.isOngoing) return false;
        const pDateStr = p.startDate || p.date;
        if (!pDateStr) return false;
        let pMonth = '';
        if (/^\d{4}-\d{2}/.test(pDateStr)) {
          pMonth = pDateStr.slice(0, 7);
        } else {
          const d = parseTimestampHelper(pDateStr);
          if (d && !isNaN(d.getTime())) {
            pMonth = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;
          }
        }
        return pMonth === selectedFsmMonth;
      });

      if (finished.length === 0) return "N/A";

      const totalSecs = finished.reduce((sum, p) => {
        if (p.durationSeconds !== undefined && p.durationSeconds > 0) return sum + p.durationSeconds;
        if (p.startDate && p.startTime && p.endDate && p.endTime) {
          try {
            const start = new Date(`${p.startDate}T${p.startTime}`);
            const end = new Date(`${p.endDate}T${p.endTime}`);
            const diff = Math.max(0, Math.floor((end.getTime() - start.getTime()) / 1000));
            return sum + diff;
          } catch {
            return sum;
          }
        }
        return sum;
      }, 0);

      const avgSecs = totalSecs / finished.length;
      const minutes = Math.round(avgSecs / 60);
      return minutes > 0 ? `${minutes} min(s)` : "N/A";
    }

    const avgMinutes = Math.round(totalDurationMinutes / countedInterventions);
    return `${avgMinutes} min(s)`;
  }, [fsmTours, generatedReports, variables, pointages, selectedFsmMonth]);

  // Historique persistant des valeurs CO2 des tournées faites / effectuées (conservé même en cas de suppression)
  const [fsmCo2History, setFsmCo2History] = useState<{
    tourId: string;
    monthKey: string;
    co2Saved: number;
    tourDate?: string;
    missionsCount?: number;
    status?: string;
  }[]>(() => {
    try {
      const raw = localStorage.getItem(`defib_${tenantId}_fsm_co2_history`) || localStorage.getItem('defib_fsm_co2_history');
      if (raw) {
        const parsed = JSON.parse(raw);
        return Array.isArray(parsed) ? parsed : [];
      }
    } catch (e) {
      console.warn("Failed to parse fsmCo2History:", e);
    }
    return [];
  });

  // Recharger l'historique CO2 si le tenant change
  useEffect(() => {
    try {
      const raw = localStorage.getItem(`defib_${tenantId}_fsm_co2_history`);
      if (raw) {
        const parsed = JSON.parse(raw);
        setFsmCo2History(Array.isArray(parsed) ? parsed : []);
      } else {
        setFsmCo2History([]);
      }
    } catch {
      setFsmCo2History([]);
    }
  }, [tenantId]);

  // Sauvegarde un enregistrement CO2 dans l'historique persistant et Firestore
  const saveCo2HistoryRecord = (record: {
    tourId: string;
    monthKey: string;
    co2Saved: number;
    tourDate?: string;
    missionsCount?: number;
    status?: string;
  }) => {
    setFsmCo2History(prev => {
      const safePrev = Array.isArray(prev) ? prev : [];
      const filtered = safePrev.filter(r => r.tourId !== record.tourId);
      const updated = [...filtered, record];
      try {
        localStorage.setItem(`defib_${tenantId}_fsm_co2_history`, JSON.stringify(updated));
      } catch (e) {
        console.warn("Storage quota exceeded in fsmCo2History:", e);
      }
      saveCollectionToFirestore('fsmCo2History', updated, tenantId);
      return updated;
    });
  };

  // Comptage persistant et inaltérable des missions Effectuée et Rejet mission par mois
  // Enregistré en DB/Firebase et localStorage pour ne jamais perdre l'historique même si une mission rejetée est retraitée
  const [fsmMissionCounts, setFsmMissionCounts] = useState<{
    monthKey: string;
    effectueesCount: number;
    rejeteesCount: number;
    recordedEvents?: string[];
  }[]>(() => {
    try {
      const raw = localStorage.getItem(`defib_${tenantId}_fsm_mission_counts`) || localStorage.getItem('defib_fsm_mission_counts');
      if (raw) {
        const parsed = JSON.parse(raw);
        return Array.isArray(parsed) ? parsed : [];
      }
    } catch (e) {
      console.warn("Failed to parse fsmMissionCounts:", e);
    }
    return [];
  });

  // Recharger le comptage persistant des missions si le tenant change
  useEffect(() => {
    try {
      const raw = localStorage.getItem(`defib_${tenantId}_fsm_mission_counts`);
      if (raw) {
        const parsed = JSON.parse(raw);
        setFsmMissionCounts(Array.isArray(parsed) ? parsed : []);
      } else {
        setFsmMissionCounts([]);
      }
    } catch {
      setFsmMissionCounts([]);
    }
  }, [tenantId]);

  // Enregistre de manière inaltérable le comptage d'une mission (Effectuée ou Rejet mission)
  const recordMissionOutcome = (monthKey: string, outcome: 'effectue' | 'rejet', eventId: string) => {
    if (!monthKey) return;
    setFsmMissionCounts(prev => {
      const safePrev = Array.isArray(prev) ? prev : [];
      const month = monthKey;
      let monthIdx = safePrev.findIndex(item => item && item.monthKey === month);
      let existing = monthIdx !== -1 ? { ...safePrev[monthIdx] } : {
        monthKey: month,
        effectueesCount: 0,
        rejeteesCount: 0,
        recordedEvents: []
      };

      const recordedEvents = Array.isArray(existing.recordedEvents) ? [...existing.recordedEvents] : [];
      if (eventId && recordedEvents.includes(eventId)) {
        return safePrev;
      }
      if (eventId) {
        recordedEvents.push(eventId);
      }

      const updatedItem = {
        ...existing,
        effectueesCount: outcome === 'effectue' ? (existing.effectueesCount || 0) + 1 : (existing.effectueesCount || 0),
        rejeteesCount: outcome === 'rejet' ? (existing.rejeteesCount || 0) + 1 : (existing.rejeteesCount || 0),
        recordedEvents
      };

      let updated: typeof safePrev;
      if (monthIdx !== -1) {
        updated = [...safePrev];
        updated[monthIdx] = updatedItem;
      } else {
        updated = [...safePrev, updatedItem];
      }

      try {
        localStorage.setItem(`defib_${tenantId}_fsm_mission_counts`, JSON.stringify(updated));
      } catch (e) {
        console.warn("Storage quota exceeded in fsmMissionCounts:", e);
      }
      saveCollectionToFirestore('fsmMissionCounts', updated, tenantId);
      return updated;
    });
  };

  // Auto-synchronisation des missions effectuées et rejetées dans le comptage persistant fsmMissionCounts
  useEffect(() => {
    if (!Array.isArray(fsmTours) || fsmTours.length === 0) return;

    setFsmMissionCounts(prevCounts => {
      const safePrevCounts = Array.isArray(prevCounts) ? prevCounts : [];
      let hasChanges = false;
      const nextCounts = [...safePrevCounts];

      fsmTours.forEach(tour => {
        if (!tour || tour.id === 'a-trier') return;
        const monthKey = getTourMonthKey(tour);
        if (!monthKey) return;
        if (!Array.isArray(tour.missions)) return;

        tour.missions.forEach((m: any) => {
          if (!m || !m.id) return;
          const sit = String(m.status || '').trim().toLowerCase();

          if (sit === 'effectué' || sit === 'effectue' || sit === 'effectuée') {
            const eventId = `sync_${tour.id}_${m.id}_effectue`;
            let monthIdx = nextCounts.findIndex(c => c.monthKey === monthKey);
            if (monthIdx === -1) {
              nextCounts.push({
                monthKey,
                effectueesCount: 0,
                rejeteesCount: 0,
                recordedEvents: []
              });
              monthIdx = nextCounts.length - 1;
            }
            const recEvents = nextCounts[monthIdx].recordedEvents || [];
            const alreadyRecorded = recEvents.some(e => e.includes(`${m.id}_effectue`));
            if (!alreadyRecorded) {
              hasChanges = true;
              nextCounts[monthIdx] = {
                ...nextCounts[monthIdx],
                effectueesCount: (nextCounts[monthIdx].effectueesCount || 0) + 1,
                recordedEvents: [...recEvents, eventId]
              };
            }
          } else if (sit === 'rejet mission' || sit === 'rejet' || sit === 'rejeté' || sit === 'rejetée') {
            const eventId = `sync_${tour.id}_${m.id}_rejet`;
            let monthIdx = nextCounts.findIndex(c => c.monthKey === monthKey);
            if (monthIdx === -1) {
              nextCounts.push({
                monthKey,
                effectueesCount: 0,
                rejeteesCount: 0,
                recordedEvents: []
              });
              monthIdx = nextCounts.length - 1;
            }
            const recEvents = nextCounts[monthIdx].recordedEvents || [];
            const alreadyRecorded = recEvents.some(e => e.includes(`${m.id}_rejet`));
            if (!alreadyRecorded) {
              hasChanges = true;
              nextCounts[monthIdx] = {
                ...nextCounts[monthIdx],
                rejeteesCount: (nextCounts[monthIdx].rejeteesCount || 0) + 1,
                recordedEvents: [...recEvents, eventId]
              };
            }
          }
        });
      });

      if (hasChanges) {
        try {
          localStorage.setItem(`defib_${tenantId}_fsm_mission_counts`, JSON.stringify(nextCounts));
        } catch (_) {}
        saveCollectionToFirestore('fsmMissionCounts', nextCounts, tenantId);
        return nextCounts;
      }
      return prevCounts;
    });
  }, [fsmTours, tenantId]);

  // Liste des mois disponibles pour le sélecteur (ex: "Février 2026", "Septembre 2026", etc.)
  const availableFsmMonths = useMemo(() => {
    const monthsMap = new Map<string, string>();
    const FRENCH_MONTH_NAMES = [
      'Janvier', 'Février', 'Mars', 'Avril', 'Mai', 'Juin',
      'Juillet', 'Août', 'Septembre', 'Octobre', 'Novembre', 'Décembre'
    ];

    const addMonth = (key: string) => {
      if (!key || !key.includes('-')) return;
      const [yStr, mStr] = key.split('-');
      const y = parseInt(yStr, 10);
      const m = parseInt(mStr, 10);
      if (isNaN(y) || isNaN(m) || m < 1 || m > 12) return;
      const label = `${FRENCH_MONTH_NAMES[m - 1]} ${y}`;
      monthsMap.set(key, label);
    };

    // Période courante étendue (-12 mois à +6 mois)
    const now = new Date();
    const curY = now.getFullYear();
    const curM = now.getMonth();
    for (let i = -12; i <= 6; i++) {
      const d = new Date(curY, curM + i, 1);
      const k = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;
      addMonth(k);
    }

    // Ajouter les mois présents dans fsmTours
    (Array.isArray(fsmTours) ? fsmTours : []).forEach(t => {
      const k = getTourMonthKey(t);
      if (k) addMonth(k);
    });

    // Ajouter les mois présents dans generatedReports
    (Array.isArray(generatedReports) ? generatedReports : []).forEach(r => {
      const k = getReportMonthKey(r);
      if (k) addMonth(k);
    });

    // Ajouter les mois présents dans l'historique
    (Array.isArray(fsmCo2History) ? fsmCo2History : []).forEach(h => {
      if (h && h.monthKey) addMonth(h.monthKey);
    });

    // Ajouter les mois présents dans l'historique de comptage des missions
    (Array.isArray(fsmMissionCounts) ? fsmMissionCounts : []).forEach(mc => {
      if (mc && mc.monthKey) addMonth(mc.monthKey);
    });

    const entries = Array.from(monthsMap.entries()).map(([key, label]) => ({ key, label }));
    entries.sort((a, b) => b.key.localeCompare(a.key)); // Plus récent en premier
    return entries;
  }, [fsmTours, generatedReports, fsmCo2History, fsmMissionCounts]);

  // Calcul du CO2 préservé (émissions évitées) pour le mois sélectionné
  // Basé sur le calcul des divs bleues des missions (1.2 kg par mission)
  // Conserve en mémoire les tournées supprimées si elles ont été faites
  const totalPreservedCo2 = useMemo(() => {
    const activeToursInMonth = (Array.isArray(fsmTours) ? fsmTours : []).filter(t => {
      if (t.id === 'a-trier') return false;
      const mKey = getTourMonthKey(t);
      return mKey === selectedFsmMonth;
    });

    const activeTourIds = new Set(activeToursInMonth.map(t => t.id));
    const activeCo2 = activeToursInMonth.reduce((sum, t) => {
      const mLength = t.missions ? t.missions.length : 0;
      return sum + (mLength * 1.2);
    }, 0);

    // Tournées supprimées mais qui ont été effectuées et conservées en historique
    const archivedCo2 = (Array.isArray(fsmCo2History) ? fsmCo2History : [])
      .filter(rec => rec && rec.monthKey === selectedFsmMonth && !activeTourIds.has(rec.tourId))
      .reduce((sum, rec) => sum + (rec.co2Saved || 0), 0);

    return Number((activeCo2 + archivedCo2).toFixed(2));
  }, [fsmTours, fsmCo2History, selectedFsmMonth]);

  const formattedCo2Str = useMemo(() => {
    if (totalPreservedCo2 === 0) return '0';
    return totalPreservedCo2 % 1 === 0 ? totalPreservedCo2.toFixed(0) : totalPreservedCo2.toFixed(1).replace('.', ',');
  }, [totalPreservedCo2]);

  // Taux de complétion des missions pour le mois sélectionné (comparaison Effectuée vs Rejet mission)
  // Comptage persistant et inaltérable dans DB/firebase même si une mission rejetée est retraitée
  const missionCompletionRateStr = useMemo(() => {
    if (!selectedFsmMonth) return "N/A";

    const monthRecord = (Array.isArray(fsmMissionCounts) ? fsmMissionCounts : []).find(r => r && r.monthKey === selectedFsmMonth);
    let effectuees = monthRecord?.effectueesCount || 0;
    let rejetees = monthRecord?.rejeteesCount || 0;

    // Compter également les missions actuelles des tournées actives du mois
    const activeToursInMonth = (Array.isArray(fsmTours) ? fsmTours : []).filter(t => {
      if (!t || t.id === 'a-trier') return false;
      return getTourMonthKey(t) === selectedFsmMonth;
    });

    let liveEffectuees = 0;
    let liveRejetees = 0;
    activeToursInMonth.forEach(t => {
      if (!Array.isArray(t.missions)) return;
      t.missions.forEach((m: any) => {
        const sit = String(m.status || '').trim().toLowerCase();
        if (sit === 'effectué' || sit === 'effectue' || sit === 'effectuée') {
          liveEffectuees++;
        } else if (sit === 'rejet mission' || sit === 'rejet' || sit === 'rejeté' || sit === 'rejetée') {
          liveRejetees++;
        }
      });
    });

    const finalEffectuees = Math.max(effectuees, liveEffectuees);
    const finalRejetees = Math.max(rejetees, liveRejetees);

    const total = finalEffectuees + finalRejetees;
    if (total === 0) return "N/A";

    const pct = (finalEffectuees / total) * 100;
    return pct % 1 === 0 ? `${pct.toFixed(0)} %` : `${pct.toFixed(1).replace('.', ',')} %`;
  }, [selectedFsmMonth, fsmMissionCounts, fsmTours]);

  const optimizeFsmTour = async (
    tourId: string,
    currentToursList: any[] = fsmTours,
    currentMembersList: Member[] = members
  ) => {
    const tour = currentToursList.find(t => t.id === tourId);
    if (!tour) return;

    if (!tour.techName || tour.techName === 'Aucun' || tour.techName.trim() === '') {
      return;
    }

    const tech = currentMembersList.find(m => m.name.trim().toLowerCase() === tour.techName.trim().toLowerCase());
    const hasTechStructured = tech && tech.startAddressLat !== undefined && tech.startAddressLng !== undefined;
    const hasTechString = tech && tech.startAddress && tech.startAddress.trim() !== '';
    if (!tech || (!hasTechStructured && !hasTechString)) {
      return;
    }

    try {
      let startCoord: { lat: number; lng: number } | null = null;
      if (tech.startAddressLat !== undefined && tech.startAddressLng !== undefined) {
        const parsedLat = Number(tech.startAddressLat);
        const parsedLng = Number(tech.startAddressLng);
        if (!isNaN(parsedLat) && !isNaN(parsedLng)) {
          startCoord = { lat: parsedLat, lng: parsedLng };
        }
      }
      if (!startCoord && tech.startAddress) {
        startCoord = await geocodeAddress(tech.startAddress);
      }

      if (!startCoord) {
        console.warn("Could not determine starting coordinates for technician:", tech.name);
        return;
      }

      const equipmentCoords: Record<string, { lat: number; lng: number }> = {};
      const equipmentDetails: Record<string, any> = {};

      tour.missions.forEach((m: any) => {
        const defib = defibrillateurs.find(d => d.identifiant === m.defibIdentifiant);
        if (defib) {
          equipmentDetails[m.defibIdentifiant] = defib;
          const lat = parseFloat(defib.latitude);
          const lng = parseFloat(defib.longitude);
          if (!isNaN(lat) && !isNaN(lng)) {
            equipmentCoords[m.defibIdentifiant] = { lat, lng };
          }
        } else {
          const other = otherEquipments.find(o => o.identifiant === m.defibIdentifiant);
          if (other) {
            equipmentDetails[m.defibIdentifiant] = other;
            const lat = parseFloat(other.latitude);
            const lng = parseFloat(other.longitude);
            if (!isNaN(lat) && !isNaN(lng)) {
              equipmentCoords[m.defibIdentifiant] = { lat, lng };
            }
          }
        }
      });

      const preference = tech.optimizationPreference || 'proche';
      const sortedMissions = sortMissionsByProximity(tour.missions, startCoord, equipmentCoords, preference as any);

      // Determine first mission travel hours from technician departure address
      let firstCoord = (sortedMissions.length > 0 && sortedMissions[0].defibIdentifiant)
        ? equipmentCoords[sortedMissions[0].defibIdentifiant]
        : null;

      if (!firstCoord && sortedMissions.length > 0) {
        const firstDefib = defibrillateurs.find(d => d.identifiant === sortedMissions[0].defibIdentifiant);
        const firstOther = otherEquipments.find(o => o.identifiant === sortedMissions[0].defibIdentifiant);
        const eq = firstDefib || firstOther;
        if (eq) {
          const addressStr = [eq.numVoie, eq.cp, eq.ville].filter(Boolean).join(' ');
          if (addressStr.trim()) {
            firstCoord = await geocodeAddress(addressStr);
            if (firstCoord) {
              equipmentCoords[sortedMissions[0].defibIdentifiant] = firstCoord;
            }
          }
        }
      }

      const firstMissionTravelHours = (startCoord && firstCoord)
        ? await calculateFirstMissionTravelHours(startCoord, firstCoord)
        : (startCoord ? 1 : 0);

      const scheduledMissions = scheduleMissions(
        sortedMissions,
        tour.startDate,
        equipmentDetails,
        tech,
        firstMissionTravelHours,
        variables,
        cttGlobalRules,
        currentToursList
      );

      const updatedTours = currentToursList.map(t => {
        if (t.id === tourId) {
          return {
            ...t,
            missions: scheduledMissions,
            calculated: true
          };
        }
        return t;
      });

      setFsmTours(updatedTours);
      localStorage.setItem(`defib_${tenantId}_fsm_tours`, JSON.stringify(updatedTours));
      if (isFirebaseLoaded && tenantId === loadedTenantIdRef.current) {
        saveCollectionToFirestore('fsmTours', updatedTours, tenantId);
      }
    } catch (err) {
      console.error("Failed to optimize tour:", tourId, err);
    }
  };

  const addFsmTour = () => {
    const hasFsmSpreadsheet = Boolean(
      getTenantSpreadsheetUrl('spreadsheetTournees', companyInfo) ||
        getTenantSpreadsheetUrl('spreadsheetMissionsTournees', companyInfo)
    );
    if (!hasFsmSpreadsheet) return;
    const newId = 'fsm-tour-' + Date.now();
    const defaultTech = '';
    const assignedVehicle = 'Aucun';
    setFsmTourDrafts(prev => ({
      ...prev,
      [newId]: {
        title: 'Nouvelle Tournée',
        techName: defaultTech,
        vehicule: assignedVehicle
      }
    }));
    const newTour = {
      id: newId,
      title: 'Nouvelle Tournée',
      techName: defaultTech,
      startDate: new Date().toISOString().split('T')[0],
      status: 'Brouillon',
      missions: [],
      vehicule: assignedVehicle,
      calculated: false
    };
    saveFsmTours([newTour, ...fsmTours]);
    setFsmDateFilter(newId);
    setFsmSystemInfoMessage("La tournée est créée, elle est accessible via la sélection de la tournée.");
    if (fsmSystemInfoTimeoutRef.current) {
      clearTimeout(fsmSystemInfoTimeoutRef.current);
    }
    fsmSystemInfoTimeoutRef.current = setTimeout(() => {
      setFsmSystemInfoMessage(null);
    }, 8000);
  };

  const deleteFsmTour = (tourId: string) => {
    const tour = fsmTours.find(t => t.id === tourId);
    if (!tour) return;
    const currentStatus = tour.status || 'Brouillon';
    if (currentStatus === 'À faire' || currentStatus === 'En cours') {
      alert("Impossible de supprimer une tournée dont le statut est À faire ou En cours.");
      return;
    }

    // Log suspicious activity Event G: delete tour
    try {
      const tourName = tour.title || tour.id || 'Tournée';
      logDeleteTour(tenantId, tourName, loggedUser?.name).catch(() => {});
    } catch (_) {}

    // Conserver en mémoire les émissions préservées (CO2) si la tournée a été faite / effectuée
    const wasDone = 
      currentStatus === 'Effectué' || 
      currentStatus === 'Terminé' ||
      (tour.missions && tour.missions.some((m: any) => m.status === 'Effectué' || m.validated)) ||
      (generatedReports && generatedReports.some((r: any) => r.tourId === tour.id || (tour.missions && tour.missions.some((m: any) => m.interventionReference === r.interventionReference))));

    if (wasDone) {
      const mLength = tour.missions ? tour.missions.length : 0;
      const co2 = Number((mLength * 1.2).toFixed(2));
      const mKey = getTourMonthKey(tour) || (tour.startDate && tour.startDate.includes('-') ? tour.startDate.slice(0, 7) : '') || currentMonthKey;
      if (co2 > 0 && mKey) {
        saveCo2HistoryRecord({
          tourId: tour.id,
          monthKey: mKey,
          co2Saved: co2,
          tourDate: tour.startDate || tour.date || '',
          missionsCount: mLength,
          status: currentStatus
        });
      }
    }
    if (tour.missions) {
      let updatedStocks = stocks.map(st => ({
        ...st,
        quantite: Number(st.quantite) || 0,
        quantiteReservee: Number(st.quantiteReservee) || 0
      }));
      let mutated = false;
      tour.missions.forEach((mission: any) => {
        if (mission.requiredParts && mission.requiredParts.length > 0) {
          mission.requiredParts.forEach((partName: string) => {
            const idx = updatedStocks.findIndex(st => {
              const vObj = variables.find(v => v.id === st.denominationPieceId);
              return vObj && (vObj.nom === partName || partName.startsWith(vObj.nom)) && st.quantiteReservee > 0;
            });
            const idxToUse = idx !== -1 ? idx : updatedStocks.findIndex(st => {
              const vObj = variables.find(v => v.id === st.denominationPieceId);
              return vObj && (vObj.nom === partName || partName.startsWith(vObj.nom));
            });
            if (idxToUse !== -1) {
              const item = updatedStocks[idxToUse];
              updatedStocks[idxToUse] = {
                ...item,
                quantite: item.quantite + 1,
                quantiteReservee: Math.max(0, item.quantiteReservee - 1)
              };
              mutated = true;
            }
          });
        }
      });
      if (mutated) {
        saveStocks(updatedStocks);
      }
    }
    if (fsmDateFilter === tourId) {
      setFsmDateFilter('none');
    }
    if (fsmLastSelectedTourId === tourId) {
      setFsmLastSelectedTourId('');
    }
    saveFsmTours(fsmTours.filter(t => t.id !== tourId));
  };

  const isTechnicianMember = (m: any): boolean => {
    if (!m) return false;
    const rawRole = String(
      (m.role && m.role !== 'Collaborateur' ? m.role : '') ||
      m.categorie ||
      m.category ||
      m['Catégorie.'] ||
      m['Catégorie'] ||
      m.adminSubRole ||
      m.metier ||
      m['Métier.'] ||
      m['Métier'] ||
      m.role ||
      ''
    ).trim().toLowerCase();
    const subRole = String(m.adminSubRole || m.categorie || m.category || m['Catégorie.'] || m['Catégorie'] || '').trim().toLowerCase();
    if (rawRole.includes('tech') || rawRole === 'maintenance terrain' || subRole.includes('tech') || subRole === 'maintenance terrain') {
      return true;
    }
    return false;
  };

  const isDraftTour = (tour: any): boolean => {
    if (!tour || tour.id === 'a-trier') return false;
    const draftOverride = fsmTourDrafts[tour.id]?.status;
    const raw = String(draftOverride !== undefined ? draftOverride : (tour.status || 'Brouillon'))
      .trim()
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g, '')
      .toLowerCase();
    return raw === 'brouillon' || raw === 'planifiee' || raw === 'planifie' || raw === 'en attente' || raw === '';
  };

  const isRaisonPrestationVariable = (v: any): boolean => {
    if (!v) return false;
    const cat = String(v.category || v.categorie || v['Catégorie.'] || v['Catégorie'] || '')
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g, '')
      .toLowerCase()
      .replace(/[^a-z0-9]/g, '');
    return cat === 'modeleraisonprestation' || cat.includes('raisonprestation') || (cat.includes('raison') && !cat.includes('livraison'));
  };

  const resolveStockPieceVariable = (s: any) => {
    if (!s) return undefined;
    const rawRef = String(s.denominationPieceId || s.denominationPieceNom || s.designation || s.denom || s.nom || '').trim();
    if (!rawRef) return undefined;
    const refLower = rawRef.toLowerCase();
    return (variables || []).find(
      (v: any) =>
        v &&
        ((v.id && String(v.id).trim().toLowerCase() === refLower) ||
          (v.identifiant && String(v.identifiant).trim().toLowerCase() === refLower) ||
          (v.nom && String(v.nom).trim().toLowerCase() === refLower))
    );
  };

  const resolveStockPieceName = (s: any, vObj?: any): string => {
    if (vObj?.nom) return vObj.nom;
    const rawRef = String(s?.denominationPieceNom || s?.designation || s?.denominationPieceId || s?.denom || s?.nom || '').trim();
    if (rawRef && !rawRef.startsWith('v_')) return rawRef;
    if (s?.ugs) return `UGS ${s.ugs}`;
    return rawRef || 'Pièce en stock';
  };

  const isMissionEstimatedDateFilled = (m: any): boolean => {
    if (!m) return false;
    const val = m.estimatedDate ? String(m.estimatedDate).trim() : '';
    if (!val) return false;
    const lower = val.toLowerCase();
    if (lower === 'a trier' || lower === 'a-trier' || lower === 'non renseigné' || lower === 'non renseigne' || lower === '--' || lower === 'nc' || lower === 'null' || lower === 'undefined') {
      return false;
    }
    return true;
  };

  const isMissionEstimatedSlotFilled = (m: any): boolean => {
    if (!m) return false;
    const val = m.estimatedSlot ? String(m.estimatedSlot).trim() : '';
    if (!val) return false;
    const lower = val.toLowerCase();
    if (lower === '-- non défini --' || lower === '-- non defini --' || lower === 'non renseigné' || lower === 'non renseigne' || lower === '--' || lower === 'nc' || lower === 'null' || lower === 'undefined' || lower === 'sélectionnez un créneau' || lower === 'selectionnez un creneau') {
      return false;
    }
    return true;
  };

  const tourMissionsHaveDatesAndSlots = (tour: any): boolean => {
    if (!tour) return false;
    const missions = tour.missions || tour.passages || [];
    if (!Array.isArray(missions) || missions.length === 0) {
      return false;
    }
    return missions.every((m: any) => isMissionEstimatedDateFilled(m) && isMissionEstimatedSlotFilled(m));
  };

  const updateFsmTour = (tourId: string, fields: any) => {
    const existingTour = fsmTours.find(t => t.id === tourId);
    const oldStatus = existingTour?.status || 'Brouillon';
    const newStatus = fields.status || oldStatus;

    if (fields.status !== undefined && (fields.status === 'À faire' || fields.status === 'En cours' || fields.status === 'Effectué')) {
      if (!tourMissionsHaveDatesAndSlots(existingTour)) {
        alert("Une ou plusieurs de vos missions n’ont pas de dates et créneaux renseignés.");
        return;
      }
    }

    const techChanged = fields.techName !== undefined && fields.techName !== existingTour?.techName;
    const dateChanged = fields.startDate !== undefined && fields.startDate !== existingTour?.startDate;
    const isCalculatedValue = (techChanged || dateChanged) ? false : (existingTour?.calculated ?? false);

    const updatedTours = fsmTours.map(t => t.id === tourId ? { ...t, ...fields, calculated: isCalculatedValue } : t);
    saveFsmTours(updatedTours);

    if (newStatus === 'Effectué' && existingTour) {
      const tourMissions = fields.missions !== undefined ? fields.missions : existingTour.missions;
      const mLength = tourMissions ? tourMissions.length : 0;
      const co2 = Number((mLength * 1.2).toFixed(2));
      const sDate = fields.startDate !== undefined ? fields.startDate : existingTour.startDate;
      const mKey = (sDate && sDate.includes('-')) ? sDate.slice(0, 7) : currentMonthKey;
      if (co2 > 0 && mKey) {
        saveCo2HistoryRecord({
          tourId,
          monthKey: mKey,
          co2Saved: co2,
          tourDate: sDate || '',
          missionsCount: mLength,
          status: 'Effectué'
        });
      }
    }

    if (newStatus === 'À faire' && oldStatus !== 'À faire' && existingTour) {
      const companyName = (companyInfo.nomCommercial || companyInfo.name || '').trim() || 'Défibeo Solutions';
      const companyEmail = companyInfo.email || '';
      
      const tourTitle = fields.title !== undefined ? fields.title : (existingTour.title || '');
      const techName = fields.techName !== undefined ? fields.techName : (existingTour.techName || '');
      const startDate = fields.startDate !== undefined ? fields.startDate : (existingTour.startDate || '');
      
      let formattedDate = startDate;
      if (startDate && startDate.includes('-')) {
        const parts = startDate.split('-');
        if (parts.length === 3) {
          formattedDate = `${parts[2]}/${parts[1]}/${parts[0]}`;
        }
      }

      // Email 8: NOUVELLE TOURNÉE POUR LE TECHNICIEN
      try {
        const matchingTech = members.find(m => m.name.trim().toLowerCase() === (techName || '').trim().toLowerCase());
        const techEmail = matchingTech?.email;
        if (techEmail && techEmail.trim()) {
          triggerEmail8NouvelleTourneeTech(
            techEmail.trim(),
            tourTitle || 'Tournée d’interventions',
            formattedDate || 'prochainement',
            companyName,
            companyEmail
          ).catch(e => console.error("Error sending Email 8:", e));
        }
      } catch (err8) {
        console.error("Error triggering Email 8:", err8);
      }
    }
  };

  const addFsmMission = (tourId: string) => {
    const newMissionId = 'fsm-m-' + Date.now();
    const newMission = {
      id: newMissionId,
      clientName: 'Nouveau Site Client',
      defibIdentifiant: 'PAR-101',
      reason: '',
      reasons: [],
      requiredParts: [],
      status: 'Brouillon',
      priority: 'Normale',
      time: '14:00',
      interventionReference: `INT-2026-${String(Date.now()).slice(-5)}`,
      autreReference: ''
    };
    const updatedTours = fsmTours.map(t => {
      if (t.id === tourId) {
        return { ...t, missions: [...t.missions, newMission], calculated: false };
      }
      return t;
    });
    saveFsmTours(updatedTours);
  };

  const deleteFsmMission = (tourId: string, missionId: string) => {
    const tour = fsmTours.find(t => t.id === tourId);
    const mission = tour?.missions.find((m: any) => m.id === missionId);
    if (mission && mission.requiredParts && mission.requiredParts.length > 0) {
      let updatedStocks = stocks.map(st => ({
        ...st,
        quantite: Number(st.quantite) || 0,
        quantiteReservee: Number(st.quantiteReservee) || 0
      }));
      let mutated = false;
      mission.requiredParts.forEach((partName: string) => {
        const idx = updatedStocks.findIndex(st => {
          const vObj = variables.find(v => v.id === st.denominationPieceId);
          return vObj && (vObj.nom === partName || partName.startsWith(vObj.nom)) && st.quantiteReservee > 0;
        });
        const idxToUse = idx !== -1 ? idx : updatedStocks.findIndex(st => {
          const vObj = variables.find(v => v.id === st.denominationPieceId);
          return vObj && (vObj.nom === partName || partName.startsWith(vObj.nom));
        });
        if (idxToUse !== -1) {
          const item = updatedStocks[idxToUse];
          let updatedTraces = Array.isArray(item.traceabilities) ? [...item.traceabilities] : [];
          if (updatedTraces.length > 0) {
            const traceToClearIdx = updatedTraces.findIndex(tr => tr.situation === 'Indisponible' || tr.reservationInfo);
            if (traceToClearIdx !== -1) {
              updatedTraces[traceToClearIdx] = {
                ...updatedTraces[traceToClearIdx],
                situation: 'Disponible',
                reservationInfo: undefined,
                bonCommande: undefined,
                client: undefined,
                dateEstimee: undefined
              };
            }
          }
          updatedStocks[idxToUse] = {
            ...item,
            quantite: item.quantite + 1,
            quantiteReservee: Math.max(0, item.quantiteReservee - 1),
            traceabilities: updatedTraces
          };
          mutated = true;
        }
      });
      if (mutated) {
        saveStocks(updatedStocks);
      }
    }

    const updatedTours = fsmTours.map(t => {
      if (t.id === tourId) {
        return { ...t, missions: t.missions.filter(m => m.id !== missionId), calculated: false };
      }
      return t;
    });
    saveFsmTours(updatedTours);
  };

  const moveFsmMissionToATrier = (tourId: string, missionId: string) => {
    const sourceTour = fsmTours.find(t => t.id === tourId);
    if (!sourceTour) return;
    const missionToMove = sourceTour.missions?.find((m: any) => m.id === missionId);
    if (!missionToMove) return;

    let aTrierExists = false;
    let updatedTours = fsmTours.map(tour => {
      if (tour.id === 'a-trier') {
        aTrierExists = true;
        const exists = (tour.missions || []).some((m: any) => m.id === missionId);
        return {
          ...tour,
          missions: exists ? tour.missions : [...(tour.missions || []), missionToMove]
        };
      }
      if (tour.id === tourId) {
        return {
          ...tour,
          missions: (tour.missions || []).filter((m: any) => m.id !== missionId),
          calculated: false
        };
      }
      return tour;
    });

    if (!aTrierExists) {
      updatedTours.push({
        id: 'a-trier',
        title: 'Missions à trier',
        startDate: 'A trier',
        status: 'Brouillon',
        missions: [missionToMove]
      });
    }

    saveFsmTours(updatedTours);
  };

  const toggleSelectFsmMission = (missionId: string) => {
    setSelectedFsmMissionIds(prev =>
      prev.includes(missionId) ? prev.filter(id => id !== missionId) : [...prev, missionId]
    );
  };

  const bulkMoveFsmMissionsToATrier = () => {
    if (selectedFsmMissionIds.length === 0) return;
    const missionsToMove: any[] = [];
    fsmTours.forEach(tour => {
      (tour.missions || []).forEach((m: any) => {
        if (selectedFsmMissionIds.includes(m.id)) {
          missionsToMove.push(m);
        }
      });
    });

    if (missionsToMove.length === 0) {
      setSelectedFsmMissionIds([]);
      return;
    }

    let aTrierExists = false;
    let updatedTours = fsmTours.map(tour => {
      if (tour.id === 'a-trier') {
        aTrierExists = true;
        const existingIds = new Set((tour.missions || []).map((m: any) => m.id));
        const newMissions = missionsToMove.filter(m => !existingIds.has(m.id));
        return {
          ...tour,
          missions: [...(tour.missions || []), ...newMissions],
          calculated: false
        };
      }
      return {
        ...tour,
        missions: (tour.missions || []).filter((m: any) => !selectedFsmMissionIds.includes(m.id)),
        calculated: false
      };
    });

    if (!aTrierExists) {
      updatedTours.push({
        id: 'a-trier',
        title: 'Missions à trier',
        startDate: 'A trier',
        status: 'Brouillon',
        missions: missionsToMove
      });
    }

    saveFsmTours(updatedTours);
    setSelectedFsmMissionIds([]);
    setIsFsmBulkTourDropdownOpen(false);
  };

