  const saveDefibs = async (newDefibs: Defibrillateur[]): Promise<void> => {
    if (isDeveloper) {
      alert("Action non autorisée : Le rôle Développeur est en mode lecture seule.");
      return;
    }
    setDefibrillateurs(newDefibs);
    loadedDataRef.current.defibrillateurs = getCollectionFingerprint(newDefibs);

    // Persist to IndexedDB/localStorage asynchronously in background so UI and network calls never block
    Promise.resolve().then(async () => {
      if (newDefibs.length <= 250) {
        const str = JSON.stringify(newDefibs);
        safeSetLocalStorage(`defib_${tenantId}_defibrillateurs`, str);
        safeSetLocalStorage(`fs_cache_${tenantId}_defibrillateurs`, str);
      }
      try {
        await idbSet(`defib_${tenantId}_defibrillateurs_v110`, newDefibs);
        await idbSet(`${tenantId}_defibrillateurs_v110`, newDefibs);
        const tAliases = getTenantAliases(tenantId);
        if (tAliases.has('d27') || tAliases.has('d58')) {
          await idbSet('defib_D27_defibrillateurs_v110', newDefibs);
          await idbSet('defib_D58_defibrillateurs_v110', newDefibs);
        }
      } catch (_) {}

      const isDNum = /^d\d+$/i.test(tenantId);
      if (isDNum) {
        const numOnly = tenantId.replace(/^d/i, '');
        try {
          localStorage.removeItem(`defib_D${numOnly}_defibrillateurs`);
          localStorage.removeItem(`fs_cache_D${numOnly}_defibrillateurs`);
          localStorage.removeItem(`defib_d${numOnly}_defibrillateurs`);
          localStorage.removeItem(`defib_${numOnly}_defibrillateurs`);
          localStorage.removeItem(`fs_cache_d${numOnly}_defibrillateurs`);
          localStorage.removeItem(`fs_cache_${numOnly}_defibrillateurs`);
        } catch (_) {}
      }
    });
  };

  const saveOtherEquipments = async (newItems: OtherEquipment[]): Promise<void> => {
    if (isDeveloper) {
      alert("Action non autorisée : Le rôle Développeur est en mode lecture seule.");
      return;
    }
    const prevIds = new Set(otherEquipments.map(x => x.id));
    const currentIds = new Set(newItems.map(x => x.id));
    const deletedIds = otherEquipments.filter(x => !currentIds.has(x.id)).map(x => x.id);
    setOtherEquipments(newItems);
    const str = JSON.stringify(newItems);
    safeSetLocalStorage(`defib_${tenantId}_other_equipments`, str);
    try {
      await idbSet(`defib_${tenantId}_other_equipments`, newItems);
    } catch (_) {}
    loadedDataRef.current.otherEquipments = str;
    if (tenantId) {
      const urlAutres =
        companyInfo?.spreadsheetAutresMateriels ||
        localStorage.getItem(`defib_${tenantId}_spreadsheet_autres_materiels`) ||
        '';
      if (deletedIds.length > 0) {
        fetch('/api/sheets/delete', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            tenantId,
            type: 'autresMateriels',
            keys: deletedIds,
            spreadsheetUrl: urlAutres,
          }),
        }).catch(() => {});
      }
      // Identify only newly added or modified records so we never re-append untouched items
      const prevMap = new Map(otherEquipments.map(x => [x.id, x]));
      const changedRecords = newItems.filter(item => {
        const prev = prevMap.get(item.id);
        if (!prev) return true;
        return JSON.stringify(prev) !== JSON.stringify(item);
      });
      if (changedRecords.length > 0) {
        fetch('/api/sheets/upsert', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            tenantId,
            type: 'autresMateriels',
            records: changedRecords,
            spreadsheetUrl: urlAutres,
          }),
        })
          .then(res => (res.ok ? res.json() : null))
          .then(json => {
            if (json && Array.isArray(json.records) && json.records.length > 0) {
              setOtherEquipments(prev =>
                prev.map(eq => {
                  const synced = json.records.find(
                    (r: any) => r && (r.id === eq.id || (r.identifiant && r.identifiant === eq.identifiant))
                  );
                  return synced ? { ...eq, ...synced } : eq;
                })
              );
            }
          })
          .catch(() => {});
      }
      fetch('/api/sync-collection', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          collectionName: 'otherEquipments',
          tenantId,
          value: newItems,
        }),
      }).catch(() => {});
      await saveCollectionToFirestore('otherEquipments', newItems, tenantId);
    }
  };

  // Ticket Operations
  const handleAddTicket = (ticketData: Omit<SupportTicket, 'id' | 'date' | 'status'>) => {
    const randomNum = Math.floor(100000 + Math.random() * 900000);
    const ticketId = `#${randomNum}`;
    const newTicket: SupportTicket = {
      id: ticketId,
      ...ticketData,
      date: new Date().toLocaleDateString('fr-FR', { day: '2-digit', month: '2-digit', year: 'numeric' }),
      status: 'Nouveau',
      envId: tenantId,
      tenantId: tenantId
    };
    const updated = [newTicket, ...tickets];
    syncCompartmentToGoogleSheets('crm', tickets, updated, ['id']);
    setTickets(updated);
    safeSetLocalStorage(`defib_${tenantId}_support_tickets`, JSON.stringify(updated));
    loadedDataRef.current.tickets = JSON.stringify(updated);
    if (tenantId) {
      saveCollectionToFirestore('tickets', updated, tenantId);
    }

    // Email 4: NOUVEAU SIGNALEMENT FORMULAIRE PUBLIQUE
    try {
      triggerEmail4Signalement(
        ticketData.identifiant || 'Inconnu',
        (companyInfo.nomCommercial || companyInfo.name || '').trim() || 'Défibeo Solutions',
        companyInfo.email || ''
      ).catch(e => console.error("Error triggering Email 4:", e));
    } catch (err) {
      console.error("Error sending signalement email:", err);
    }

    return ticketId;
  };

